window.TEAMS = [{"id":"6040","team":"McGill","section":"Undergrad","country":"Canada","wiki":"https://2026.igem.wiki/mcgill/","rank":14,"awards":["Best Entrepreneurship — Nominee (Undergrad)","Best Biomanufacturing Project — Nominee"],"projectTitle":"LanTurn","tagline":"Lanmodulin displayed on yeast, harvested by light-triggered flocculation, deployed on-site as a tolling service for mine tailings","summary":"McGill engineered Saccharomyces cerevisiae EBY100 to display lanmodulin variants on its surface via the Aga1-Aga2 system for selective rare-earth binding, and to flocculate on command through a blue-light VP16-EL222 / C120 optogenetic circuit driving a truncated 678FLO1 flocculin, so that REE-loaded cells can be separated by gravity settling instead of centrifugation. Light-induced flocculation reached 66-75 percent against 24-25 percent in dark controls, and LanM surface display was confirmed by flow cytometry and confocal microscopy. The commercial case is a full industrial techno-economic analysis rather than a canvas: gate-to-gate CAPEX and OPEX, a unit cost of $11.83-20.58 USD per kg REO, a full-scale NPV case study on the Ashram tailings in Nunavik, Quebec, and seven separate sensitivity analyses. They were nominated for Best Entrepreneurship (Undergrad) and Best Biomanufacturing.","images":[{"url":"https://static.igem.wiki/teams/6040/wiki/entrep-page/tab-2/pt-financial-analysis.avif","caption":"Financial analysis of the Ashram tailings re-mining case study, giving USD 51M NPV over 15 years in the high-uptake scenario against a marginally negative NPV in the low-uptake case","credit":"Team McGill, iGEM 2026 wiki"}]},{"id":"6041","team":"UOregon","section":"Overgrad","country":"United States","wiki":"https://2026.igem.wiki/uoregon/","rank":7,"awards":["Best Education — Nominee (Overgrad)"],"projectTitle":"AquaFlock","tagline":"E. coli engineered to sequester groundwater nitrate as cyanophycin, then flocculate so the nitrogen can be harvested back as fertilizer","summary":"UOregon engineered E. coli to pull excess environmental nitrate into the nitrogen storage polymer cyanophycin and, once a cyanophycin threshold is reached, to express flocculation proteins so cells sink and can be harvested as a fertilizer substitute, closing the nitrogen loop. The target users are rural well owners and farmers in Oregon whose water is rarely tested. The education practice is the standout: three original curricula built for three audiences with increasing prior knowledge, developed through an explicit Design-Build-Test-Learn loop and grounded in Universal Design for Learning plus STEAM. The team also built an offline desktop search engine indexing the full text of 1,354 iGEM team wikis and 20,761 pages from 2022-2025.","images":[{"url":"https://static.igem.wiki/teams/6041/wiki/pages/education/edu-wksp1-main-photo.avif","caption":"Workshop 1: one-hour intro to synthetic biology for 30 high school students at the Oregon Humane Society camp","credit":"Team UOregon, iGEM 2026 wiki"}]},{"id":"6043","team":"Vilnius-Lithuania","section":"Undergrad","country":"Lithuania","village":"Foundational Advance","wiki":"https://2026.igem.wiki/vilnius-lithuania/","rank":21,"awards":["Best New Basic Part — Nominee (Undergrad)","Best Software — Nominee (Undergrad)","Best Presentation — Nominee (Undergrad)"],"projectTitle":"BMClick: One Shell to Click Them All","projectTitle_zh":"BMClick：一殼點擊萬物","tagline":"Bacterial microcompartment shells rebuilt outside the cell and made programmable by click chemistry, plus Ladder Detector, which annotates a gel in about a minute.","tagline_zh":"把細菌微區室外殼在細胞外重建，並以點擊化學使其表面可程式化；另有 Ladder Detector，約一分鐘標註完一張電泳膠影像。","summary":"BMClick rebuilds bacterial microcompartments (BMCs), the proteinaceous shells bacteria use to sequester metabolic reactions, in vitro and makes their surface programmable through click chemistry at an amber-codon-incorporated non-canonical amino acid, turning a natural containment system into a modular platform for working with purified biomolecules. The aim is to recover the organisation a cell provides, protecting therapeutic nucleic acids from nucleases, separating the steps of a reconstructed pathway, and extending the temperature and pH range over which enzymes work, while keeping the precision of in vitro conditions. The project also produced functional macroscopic materials from BMC-T shell proteins, and in vitro encapsulation was demonstrated with a HiBiT-SpyCatcher cargo and confirmed by cryo-EM. The dry-lab deliverable is Ladder Detector, a React + FastAPI web app that segments bands in a gel photograph using GelGenie's released U-Net models and then identifies which commercial ladder was run in the marker lane, a step no existing tool automated.","summary_zh":"BMClick 在體外重建細菌微區室（BMC）——細菌用來區隔代謝反應的蛋白質外殼——並透過在以 amber 密碼子嵌入的非天然胺基酸上進行點擊化學，使外殼表面可程式化，把一套天然的包覆系統變成處理純化生物分子的模組化平台。目標是重現細胞所提供的組織性：保護治療用核酸不被核酸酶分解、分隔重建路徑中的各個步驟、擴大酵素可作用的溫度與 pH 範圍，同時保有體外條件的精確性。團隊也用 BMC-T 外殼蛋白做出具功能的巨觀材料，並以 HiBiT-SpyCatcher 載物示範體外包覆，再由 cryo-EM 確認。乾實驗的產出是 Ladder Detector：一個 React + FastAPI 網頁應用程式，先用 GelGenie 已釋出的 U-Net 模型分割電泳膠照片中的條帶，再判定標記道跑的是哪一種市售分子量標準品（ladder）——這一步是現有工具都沒有自動化的。","images":[{"url":"https://static.igem.wiki/teams/6043/wiki/software-images/original-photo-vs-result-2.avif","caption":"The original gel electrophoresis photograph next to Ladder Detector's automatically annotated result.","caption_zh":"原始的膠體電泳照片，與 Ladder Detector 自動標註後的結果並列。","credit":"Team Vilnius-Lithuania, iGEM 2026 wiki"}]},{"id":"6045","team":"UNILausanne","section":"Overgrad","country":"Switzerland","wiki":"https://2026.igem.wiki/unilausanne/","rank":7,"awards":["Best Measurement — Nominee (Overgrad)"],"projectTitle":"ASTACi: Detect, Disarm, Defend","tagline":"A field-deployable LAMP assay for the crayfish plague pathogen, a sub-CHF-10 open-source incubator to run it, and an ecological model that decided which treatment strategy to pursue.","summary":"UNILausanne addressed crayfish plague, caused by the oomycete Aphanomyces astaci, with three complementary strategies: detect the pathogen in water with loop-mediated isothermal amplification, disarm the invasive signal crayfish that carries it using RNAi, and defend native crayfish with a protective protein supplement. The measurement work asks whether the LAMP assay is specific enough to separate A. astaci from the closely related A. frigidophilus, sensitive enough to be useful, and robust enough to survive real lake and river water. The hardware is C.L.A.W., a hand-sized USB-powered incubator built with the original author of the MobileLAMP design, fully open-source at under CHF 10 per unit. A stochastic two-species population model was validated against a documented field case and then used to decide how to split effort between the disarm and defend strategies.","images":[{"url":"https://static.igem.wiki/teams/6045/wiki/hardware/frame-023.webp","caption":"C.L.A.W. (Compact LAMP ASTACi Water-incubator), the team's hand-sized, USB-powered LAMP incubator. It is fully open-source, built from off-the-shelf and 3D-printed parts for under CHF 10 per device.","credit":"Team UNILausanne, iGEM 2026 wiki"}]},{"id":"6053","team":"HKSSC","section":"High School","country":"Hong Kong","village":"Food & Nutrition","wiki":"https://2026.igem.wiki/hkssc/","rank":110,"awards":["Top 10 (High School)","Best New Basic Part — Winner (High School)","Best Education — Nominee (High School)","Best Village Project — Nominee (Agriculture / Food & Nutrition / Fashion & Cosmetics / Art & Design)"],"projectTitle":"Engineering E. coli to express prbA, a paraben-degrading esterase, as a pre-treatment for food waste recycling","projectTitle_zh":"改造 E. coli 表現除對羥基苯甲酸酯的酯酶 prbA，作為廚餘回收的前處理步驟","tagline":"If preservatives are designed to stop microbes, can we design microbes to stop preservatives?","tagline_zh":"既然防腐劑的設計目的是抑制微生物，我們能不能設計微生物來分解防腐劑？","summary":"HKSSC (St. Stephen's College, Hong Kong) noticed a bottleneck nobody was talking about: Hong Kong's O-PARK organic resources recovery centre runs anaerobic digestion on food waste, but the chemical preservatives already in that waste inhibit the very microbes doing the digesting. They cloned prbA, a paraben esterase from Enterobacter cloacae that hydrolyses parabens to 4-hydroxybenzoic acid and needs no complex cofactors, into pET22b+ under a T7 promoter with a pelB signal peptide directing it to the periplasm, then characterised it with CFU-based MIC assays, a pNPA esterase assay and HPLC. They won Best New Basic Part at high school level largely on the strength of the prbA part family - including the previously unregistered native promoter and RBS, which they located in silico with BPROM and then built into a promoterless GFP reporter construct. The dry lab and statistics are the standout: structure-guided mutant design in HotSpot Wizard on an AlphaFold model, and a Michaelis-Menten kinetic analysis defended with two-way ANOVA, a Brown-Forsythe Levene variance check and Welch-Satterthwaite contrasts with Holm correction.","summary_zh":"HKSSC（香港聖士提反書院）注意到一個少有人談的瓶頸：香港 O-PARK 有機資源回收中心以厭氧消化處理廚餘，但廚餘中既有的化學防腐劑會抑制負責消化的微生物本身。他們將 prbA（來自 Enterobacter cloacae 的對羥基苯甲酸酯酯酶，可將 paraben 水解為 4-hydroxybenzoic acid，且不需複雜輔因子）選殖進 pET22b+，置於 T7 啟動子下，並以 pelB 訊號肽導向周質空間，再以 CFU 為基礎的 MIC 試驗、pNPA 酯酶活性試驗與 HPLC 進行特性分析。他們以 prbA 元件家族的實力拿下高中組最佳新基礎元件獎——其中包括此前未註冊的天然啟動子與 RBS，團隊先用 BPROM 以電腦預測其位置，再建成無啟動子的 GFP 報告基因構築。乾實驗與統計是全隊亮點：以 AlphaFold 模型在 HotSpot Wizard 中進行結構導向的突變體設計，以及一套以雙因子 ANOVA、Brown-Forsythe（基於中位數的 Levene）變異數檢定與經 Holm 校正的 Welch-Satterthwaite 對比加以支撐的 Michaelis-Menten 動力學分析。","images":[{"url":"https://static.igem.wiki/teams/6053/wiki/modelling/image1.avif","caption":"The prbA paraben esterase structure retrieved from AlphaFold and visualised in UCSF Chimera; the long flexible N-terminal tail matches the 31-residue signal peptide and justified switching to pelB periplasmic targeting.","caption_zh":"取自 AlphaFold、並以 UCSF Chimera 視覺化的 prbA 對羥基苯甲酸酯酯酶結構；長而柔軟的 N 端尾巴與 31 個殘基的訊號肽相符，成為改用 pelB 周質導向的依據。","credit":"Team HKSSC, iGEM 2026 wiki"}]},{"id":"6054","team":"SJTU-BioX-Shanghai","section":"Undergrad","country":"China","wiki":"https://2026.igem.wiki/sjtu-biox-shanghai/","rank":7,"awards":["Inclusivity Award — Nominee (Undergrad)"],"projectTitle":"Dual-Armor","projectTitle_zh":"Dual-Armor（雙重護甲）","tagline":"An engineered living dressing that breaks open wound biofilm, clears pathogens and supports tissue repair in chronic wounds","tagline_zh":"一種工程化活體敷料，能破壞傷口生物膜、清除病原菌，並支持慢性傷口的組織修復","summary":"SJTU-BioX-Shanghai built Dual-Armor, an engineered-microbe dressing for chronic wounds, targeting the biofilm that a meta-analysis of 2,666 chronic wounds found in 68% of cases; about 18.6 million people develop diabetic foot ulcers each year and roughly 65% recur within five years. The team's inclusivity work is the most systematically theorised of the 2026 cohort: they built a two-layer framework in which four dimensions (VOICE, OPPORTUNITY, ACCESSIBILITY, PARTICIPATION) locate where participation is blocked and a five-step pathway, HEALS (Hear, Examine, Act, Learn, Share), governs how each barrier is answered. Twelve activities are each written up against both layers, and patient input visibly changed the product: Dual-Armor was repositioned from a stand-alone treatment to an auxiliary post-debridement dressing, and patients' fear of live bacteria touching the wound drove the physical-containment hardware design.","summary_zh":"SJTU-BioX-Shanghai 做出 Dual-Armor，一款用於慢性傷口的工程菌敷料，針對的是生物膜——一項涵蓋 2,666 例慢性傷口的統合分析發現其中 68% 有生物膜；每年約有 1,860 萬人罹患糖尿病足潰瘍，約 65% 在五年內復發。該隊的包容性工作是 2026 年各隊中理論化最系統的：他們建立了一個雙層架構，以四個面向（VOICE、OPPORTUNITY、ACCESSIBILITY、PARTICIPATION）定位參與在哪裡受阻，並以五步路徑 HEALS（Hear、Examine、Act、Learn、Share）規範每一道障礙如何被回應。十二項活動都分別對照兩個層次寫成紀錄，病人的意見也明顯改變了產品：Dual-Armor 從獨立療法重新定位為清創後的輔助敷料，而病人對活菌接觸傷口的恐懼促成了實體圍阻硬體的設計。","images":[{"url":"https://static.igem.wiki/teams/6054/wiki/images/inclusivity/braille-1.avif","caption":"'Touch Life, See Hope': writing chronic-wound knowledge onto braille postcards, with an open English toolkit released so others can run it","caption_zh":"「Touch Life, See Hope」：把慢性傷口知識寫上點字明信片，並釋出開放的英文工具包讓別人也能照著辦","credit":"Team SJTU-BioX-Shanghai, iGEM 2026 wiki"}]},{"id":"6058","team":"HK-Joint-School","section":"High School","country":"Hong Kong","village":"Manufacturing / Environment","wiki":"https://2026.igem.wiki/hk-joint-school/","rank":7,"awards":["Best Software — Nominee (High School)"],"projectTitle":"FlaminGone","tagline":"A non-toxic biological fire-retardant coating, plus PyroForge, a live protein-language-model web app that predicts thermostability from sequence alone.","summary":"FlaminGone replaces halogenated chemical fire retardants with a self-assembling biological coating: E. coli's CsgA curli subunit forms an amyloid scaffold, fused to hydrophobic BslA for weatherproofing and polyethylene-binding peptides for substrate anchoring, in a two-layer system that sidesteps secretion limits and steric hindrance. Under fire testing the matrix forms a dense char shield that halts flame propagation and self-extinguishes, BslA prevents rain washout across weathering, and Arabidopsis assays indicated no ecotoxicity. To design the fusion peptides without waiting on crystal structures, the team built PyroForge, a publicly deployed web application that uses a frozen ESM-2 650M protein language model as a feature extractor under three lightweight custom-trained heads predicting melting temperature, folding free energy and per-mutation stability change, then scans every single-residue substitution and returns a ranked shortlist. For a high school team the engineering rigour is remarkable: a published S669 benchmark against 21 competing methods, Zenodo-archived weights and datasets with DOIs, 226-respondent user acceptance testing, and documented bugs that changed the model's reported accuracy.","images":[{"url":"https://static.igem.wiki/teams/6058/wiki/software/system-archi.avif","caption":"PyroForge system architecture: Nginx reverse proxy as the only public surface, with FastAPI, Redis and three purpose-separated Celery queues (fast, heavy, io) isolated on the internal Docker network.","credit":"Team HK-Joint-School, iGEM 2026 wiki"}]},{"id":"6060","team":"DTU-Denmark","section":"Overgrad","country":"Denmark","village":"Bioremediation","wiki":"https://2026.igem.wiki/dtu-denmark/","rank":47,"awards":["Best New Basic Part — Nominee (Overgrad)","Best Presentation — Nominee (Overgrad)","Best Sustainable Development Impact — Winner (Overgrad)","Best Bioremediation Project — Nominee"],"projectTitle":"Enzymatic degradation of wind turbine blade epoxy","tagline":"A chemo-enzymatic route to the resin fraction of decommissioned wind turbine blades, assessed honestly against the alternatives","summary":"DTU engineered laccases (ItL-03 from a spruce bark beetle gut metagenome, CueO variants and homologues) and unspecific peroxygenases (PaDa-I, WamPa, PabUPO-II, MroUPO, Fett) to attack the amine crosslinks of cured epoxy from wind turbine blades, layered on top of a published acid-plus-peroxide solvolysis pretreatment. They used NNBT, a small water-soluble molecule carrying the tertiary amine of the crosslink, as a defined model substrate, and showed by MALDI-TOF that PaDa-I performs N-dealkylation on it with Purpald confirmation of lactaldehyde release. The decisive work is a prospective comparative life-cycle assessment in SimaPro (ReCiPe 2016 Midpoint H) of five end-of-life routes, which found their own enzymatic route is NOT the best option on almost any indicator - and they published that. Seven interviews across DTU Wind, DTU Sustain, DTU Chemistry, SDU and industry, plus documented non-responses from Siemens Gamesa, Orsted and MAKEEN Energy, drove changes to the chemical target, the model substrate, the host organism, the enzyme-ranking criterion and the project's stated goal.","images":[{"url":"https://static.igem.wiki/teams/6060/wiki/human-practices/stakeholder-photos/javier.webp","caption":"Javier, postdoc at DTU Sustain working on resin chemistry, whose question about whether an enzyme could replace the cleaving solvent reframed the whole project as a complement to solvolysis","credit":"Team DTU-Denmark, iGEM 2026 wiki"}]},{"id":"6064","team":"DKU","section":"Undergrad","country":"China","village":"Software & AI","wiki":"https://2026.igem.wiki/dku/","rank":7,"awards":["Best Software & AI Project — Nominee"],"projectTitle":"PeptiCraft","tagline":"An AI-assisted platform that turns a product brief into a traceable shortlist of recombinant fusion-protein candidates for skincare and medical aesthetics.","summary":"PeptiCraft addresses a specific physical problem: a free 10-30 residue bioactive peptide has essentially no structural stability, is degraded quickly by proteases, cannot be cast or gelled into a material, and diffuses away from where it is needed. The team's hypothesis is that such a peptide can be rescued by gene-fusing it to a structural scaffold, here a 364-residue recombinant Bombyx mori silk fibroin (FibLNT8-10xRep-FibHCT) chosen because its mechanical behaviour comes from sequence repeats rather than a folded globular core and therefore survives editing. The dry lab streamed 849,416,450 published protein sequences, kept the 19.9 million that are 3-30 standard residues, and ran them down an eight-round funnel to 496 assembled constructs across four functional directions, with a 99.9975% overall rejection rate. Three antioxidant candidates and a scaffold-only control were then expressed in E. coli and assayed: Top1 roughly doubled the scaffold's radical-scavenging capacity (TEAC 0.375 vs 0.195 mmol TE/g, p = 0.0075), no construct was cytotoxic to human keratinocytes, and no construct significantly protected cells against oxidative stress.","images":[{"url":"https://static.igem.wiki/teams/6064/wiki/project-20261020/image8.avif","caption":"PeptiCraft's library page safety panel, which resolves to four verdicts (clear, exceeded, borderline, not assessed) so an unmeasured gate can never be read as a passed one.","credit":"Team DKU, iGEM 2026 wiki"}]},{"id":"6072","team":"GEMS-Taiwan","section":"High School","country":"Taiwan","village":"Space, Foundational Advance, Software & AI, Biomanufacturing","wiki":"https://2026.igem.wiki/gems-taiwan/","rank":169,"awards":["Top 10 (High School)","Best Measurement — Winner (High School)","Best Hardware — Winner (High School)","Best Presentation — Nominee (High School)","Best Wiki — Nominee (High School)","Best Integrated Human Practices — Winner (High School)","Best Village Project — Nominee (Space / Foundational Advance / Software & AI / Biomanufacturing)"],"projectTitle":"ReLEAF","tagline":"A stress-responsive optogenetic bioreactor that predicts crop stress from field sensors and forecasts, then uses green light to make plant-protective proteins on the farm.","summary":"ReLEAF closes a loop: field sensors and weather forecasts feed a stress-index model, the model sets a green-light dose, green light drives the cyanobacterial CcaSR two-component system in Bacillus subtilis WB800, and the cells secrete ACC deaminase into a hollow-fiber perfusion bioreactor that lets protein out and keeps cells in. The unit is about 40 x 24 x 62 cm, designed to stand beside a Taiwanese smallholder paddy where the average agricultural manager is 63.8 years old and precision agriculture is otherwise out of reach. It swept the high-school technical awards (Measurement, Hardware, Integrated Human Practices) largely on provenance discipline: four self-built devices with release build manuals, a digital twin that caught a failing photometer 26.7 hours before it died, a pre-registered growth forecast scored against a later run, and an input ledger that marks every number as measured, cited or modelled. Its distinguishing quality is honesty — the wiki repeatedly withdraws its own claims, and that is also where its dry-lab weaknesses are visible.","images":[{"url":"https://static.igem.wiki/teams/6072/wiki/software/twin-screen-20261018-software.webp","caption":"The ReLEAF digital twin control screen on 18 October 2026, showing optical density, pH, four pressure traces and the pump and valve controls for a live bioreactor run on one page.","credit":"Team GEMS-Taiwan, iGEM 2026 wiki"}]},{"id":"6077","team":"UOttawa","section":"Undergrad","country":"Canada","village":"Bioremediation","wiki":"https://2026.igem.wiki/uottawa/","rank":110,"awards":["Top 10 (Undergrad)","Best Alternative Platform — Winner (Undergrad)","Best Wiki — Nominee (Undergrad)","Best Bioremediation Project — Nominee"],"projectTitle":"Nulfur","tagline":"Break bonds, not the fuel: engineered biodesulfurization as a polishing step for refractory sulfur in diesel.","summary":"Nulfur rebuilds the four-enzyme 4S biodesulfurization pathway (DszA, DszB, DszC plus a flavin reductase) from Rhodococcus erythropolis inside Pseudomonas putida KT2440, targeting dibenzothiophene (DBT) — the refractory sulfur compound that conventional hydrodesulfurization struggles to remove without running at 300-400 C and 3-6 MPa. Rather than replacing hydrodesulfurization, the team reframed the project after industry consultation as a modular side-stream polishing step on diesel. The project won on the strength of its alternative chassis work: because P. putida is a non-model organism, the team built the missing toolkit from scratch (a Golden Gate-compatible broad-host-range vector, a measured four-promoter set, and a working heat-shock transformation protocol) and published it as a handbook for other teams. That platform contribution, paired with an unusually deep dry lab (COBRApy genome-scale modelling, a FoldX/ThermoMPNN protein engineering pipeline, and an agentic AI research platform called Cofactor), won Best Alternative Platform and Best Wiki and Best Bioremediation Project nominations.","images":[{"url":"https://static.igem.wiki/teams/6077/wiki/dry-lab/protein-engineering/fig-3.svg","caption":"Predictor-agreement scatter for 437 scored DszB mutations: the shaded quadrant is where FoldX and ThermoMPNN both call a substitution stabilising, enlarged to label the five variants advanced to the wet lab.","credit":"Team UOttawa, iGEM 2026 wiki"}]},{"id":"6078","team":"UPF-Barcelona","section":"Undergrad","country":"Spain","village":"Food & Agriculture","wiki":"https://2026.igem.wiki/upf-barcelona/","rank":26,"awards":["Best Software — Winner (Undergrad)"],"projectTitle":"Vinesys","tagline":"Where the rain runs out, the roots hold on: engineering root-associated Bacillus subtilis to hold water around grapevine roots.","summary":"Vinesys engineers Bacillus subtilis to colonise the grapevine rhizosphere and overexpress gamma-PGA, a water-retaining biopolymer, plus ACC deaminase to trim the drought-stress hormone precursor ACC, forming a thin hydration shell where the bacterium attaches to the root. Drought is detected by a two-layer switch: an osmolarity-responsive promoter plus a salt-dependent intein (HutMCM2) that the team re-engineered in silico to splice at the roughly 600-725 mM intracellular K+ that B. subtilis actually reaches, rather than its native 1.5 M. The dry lab produced three distinct deliverables: RK4 solver, a standalone no-code genetic-circuit designer and simulator; a documented molecular-dynamics pipeline for tuning salt-dependent proteins; and iGEMforge, a Claude Code plugin of four research skills that they evaluated honestly and then declined to use for project decisions. Awards came for Software, Model and Education.","images":[{"url":"https://static.igem.wiki/teams/6078/wiki/dry-lab/software/figure6.avif","caption":"Screenshot of the RK4 solver editor with the biocontainment toxin-antitoxin circuit built from linked blocks.","credit":"Team UPF-Barcelona, iGEM 2026 wiki"}]},{"id":"6089","team":"BAID-China","section":"High School","country":"China","wiki":"https://2026.igem.wiki/baid-china/","rank":7,"awards":["Inclusivity Award — Nominee (High School)"],"projectTitle":"Neurofilux","tagline":"An AI-designed antibody sandwich assay for blood neurofilament light chain, for cheap non-invasive early screening of neurodegenerative disease","summary":"BAID-China built Neurofilux, a blood test for neurofilament light chain (NfL), a biomarker of neuronal damage that rises years before Alzheimer's or ALS symptoms appear but is currently detectable only by expensive, invasive or insufficiently sensitive methods. They expressed the NfL rod domain (residues 93-396) as antigen, used the generative model RFantibody to design candidate antibodies, screened them with a multi-objective scoring pipeline, validated eight candidates experimentally and found two pairs outperforming commercial antibodies in sandwich ELISA, then converted the validated antibodies into nanobodies for stability and cost. Their inclusivity work is organised around a self-defined 3A framework - Adaptation, Awareness, Accessibility - and centres on a tactile magnetic genetic-circuit kit for blind children, developed in two phases and donated to a school for the visually impaired.","images":[{"url":"https://static.igem.wiki/teams/6089/wiki/5.avif","caption":"Workshop Activity One: participants navigate the team's own laboratory in a wheelchair and record the barriers they meet","credit":"Team BAID-China, iGEM 2026 wiki"}]},{"id":"6090","team":"BOKU-Vienna","section":"Overgrad","country":"Austria","wiki":"https://2026.igem.wiki/boku-vienna/","rank":7,"awards":["Best Education — Nominee (Overgrad)"],"projectTitle":"Algaeneering","tagline":"Engineering the microalga Chlamydomonas reinhardtii into a vitamin C and folate factory to fight hidden hunger","summary":"BOKU-Vienna overexpressed GGP (vitamin C) and GTPCHI plus ADCS (folate) in Chlamydomonas reinhardtii using Golden Gate Level 0/1/2 assembly, reaching a 4.5x increase in vitamin C in the GGP strain. The project was framed around hidden hunger, which affects an estimated two billion people, and was linked to UN SDGs 2, 3 and 12. Its education practice was built on an explicit didactic framework (the Didactic Triangle) and spanned four goals: sparking curiosity, classroom science, public dialogue and educational media. A genome-scale metabolic model was coupled to a calibrated bioreactor model and a nutritional impact model to translate lab titres into how many people a production plant could feed.","images":[{"url":"https://static.igem.wiki/teams/6090/wiki/hp-and-education/kinderuni/kinderuni-02.avif","caption":"Children at the Children's University (KinderUNI) six-station synthetic biology booth in Vienna","credit":"Team BOKU-Vienna, iGEM 2026 wiki"}]},{"id":"6096","team":"XJTLU-China","section":"Undergrad","country":"China","wiki":"https://2026.igem.wiki/xjtlu-china/","rank":66,"awards":["Best Measurement — Nominee (Undergrad)","Best Model — Winner (Undergrad)","Best Education — Winner (Undergrad)","Best Wiki — Nominee (Undergrad)"],"projectTitle":"dogmaOS — programming translation rhythm for soluble protein expression","tagline":"Design where and for how long the ribosome should pause, then re-engineer the host tRNA pool to make that pause possible.","summary":"XJTLU-China asked whether soluble yield of hard-to-express recombinant proteins in E. coli can be improved by deliberately programming *where* translation slows down, rather than by maximising expression. Their dry-lab system catmaOS (Codon-Aware Translation Modeling and Analysis Operating System) chains four models: structural co-translational folding priority (M1), evolutionary conserved slow-codon evidence (M2), a five-layer translation-kinetics and ribosome-traffic engine with constrained Pareto selection (M3-A to M3-E), and host tRNA-pool intervention design (M4). The framework picked a single synonymous G-CSF design (W1-S) out of six candidates and an engineered BL21-AlaPro chassis, both of which went to the bench; Four-Leaf Clover RT-qPCR then measured the actual tRNA knockdown and that number was fed back into M3-A as an updated host context. It won Best Model (Undergraduate) and Best Education (Undergraduate).","images":[{"url":"https://static.igem.wiki/teams/6096/wiki/assets/drylab/model/figure-08.svg","caption":"Figure 8: exit-tunnel sensitivity heatmap. Rows are assumed ribosome exit-tunnel lengths of 30-40 codons, columns are G-CSF codon positions, and the fixed 0-100 teal scale shows structural priority. Light-grey cells mark genuinely unavailable structural data rather than a score of zero, so the reader can watch high-priority bands migrate as a modelling assumption changes.","credit":"Team XJTLU-China, iGEM 2026 wiki"}]},{"id":"6098","team":"ICJFLS","section":"High School","country":"China","wiki":"https://2026.igem.wiki/icjfls/","rank":7,"awards":["Best Entrepreneurship — Nominee (High School)"],"projectTitle":"ORA-GUARD","tagline":"An engineered oral probiotic that degrades the sulfur compounds causing halitosis instead of sterilising the mouth","summary":"ICJFLS engineered Streptococcus salivarius K12, a GRAS oral probiotic, to express a Sox enzyme cluster plus an MTO enzyme that catalytically degrade the volatile sulfur compounds (H2S, methanethiol, dimethyl sulfide) responsible for bad breath, positioning it as a Live Biotherapeutic Product rather than a mouthwash. Plasmid expression was abandoned after stability tests showed near-total plasmid loss within five days without selection, so the cassettes were moved into the chromosome by CRISPR-Cas9, and a four-layer biosafety system (D-alanine auxotrophy via alr knockout, a PcspA RNA-thermometer suicide switch, no antibiotic resistance markers) was added in direct response to public fear of live GMO bacteria. The entrepreneurship case is numerically specific, with per-dose cost, retail price, gross margin and a named contract manufacturer. They were nominated for Best Entrepreneurship in the High School section.","images":[{"url":"https://static.igem.wiki/teams/6098/wiki/entrepre/fig-3-entrepre.avif","caption":"TAM, SAM and SOM analysis for ORA-GUARD, with the SOM built bottom-up from 100,000 target users at RMB 200 per month","credit":"Team ICJFLS, iGEM 2026 wiki"}]},{"id":"6102","team":"ZJU-China","section":"Undergrad","country":"China","wiki":"https://2026.igem.wiki/zju-china/","rank":14,"awards":["Best Entrepreneurship — Nominee (Undergrad)","Best Biomanufacturing Project — Nominee"],"projectTitle":"NEST","tagline":"A sequence-defined SELP hydrogel with a SnoopTag2 plug socket, so one cartilage scaffold can be reconfigured by swapping functional peptides","summary":"ZJU-China built NEST, a silk-elastin-like protein (SELP) hydrogel carrying SnoopTag2 as a standardised ligation interface, so that repair peptides (Link-N, a chondroitin-sulfate-retaining CPC module, a magnetically responsive anisotropy module, a mitochondrial delivery module) can be attached without redesigning the material. They engineered a SnoopLigase2-ZJU variant for the ligation chemistry, purified SELP by inverse transition cycling optimised to 65 degrees C in PBS with 2 M NaCl, and validated GAG binding by AviTag-BirA site-specific biotinylation onto streptavidin beads with DMMB quantification. The commercial case is a full process-economics build rather than a canvas, with equipment, land, working capital, medium, IPTG, kanamycin, labour by shift and waste volumes all costed, plus a 2026-2042 stage-gated roadmap and a ten-year discounted cash-flow model. They were nominated for Best Entrepreneurship (Undergrad) and Best Biomanufacturing.","images":[{"url":"https://static.igem.wiki/teams/6102/wiki/images/hp/entrepreneurship/003.avif","caption":"NEST development roadmap and milestones for R&D, manufacturing, regulatory affairs, fundraising and commercialisation, 2026-2042","credit":"Team ZJU-China, iGEM 2026 wiki"}]},{"id":"6105","team":"Mingdao","section":"High School","country":"Taiwan","wiki":"https://2026.igem.wiki/mingdao/","rank":7,"awards":["Best Model — Nominee (High School)"],"projectTitle":"Waste-to-Watt — bioethanol from plastic-coated paper containers","tagline":"Turn the coffee cups and lunch boxes 7,000 students throw away every day into fuel, by pairing enzymes with a glucose-eating microbe in one pot.","summary":"Mingdao take used paper containers — coffee cups, lunch boxes, ramen bowls — and break their cellulose to glucose with an enzyme cocktail for fermentation to bioethanol. The obstacle is end-product inhibition: cellulase is inhibited by cellobiose and beta-glucosidase by glucose. Their answer is Simultaneous Saccharification and Fermentation, putting Zymomonas mobilis in the same vessel as a glucose sink so neither enzyme ever sees inhibitory product. Three models carry it: a Michaelis-Menten competitive-inhibition fit to their own pNPG assay data giving Km, Vmax and Ki for BglA at fermentation-compatible conditions; a Monod fit to their own Z. mobilis growth curves giving mu_max, Ks and biomass yield; and a coupled ODE in SciPy that feeds every one of those measured parameters into a closed-versus-open simulation of the real one-pot reactor. Every parameter in model three came from their own bench.","images":[{"url":"https://static.igem.wiki/teams/6105/wiki/model2.avif","caption":"The Waste-to-Watt SSF fermentor: cellulase and beta-glucosidase saccharify paper-container cellulose to glucose while Zymomonas mobilis simultaneously ferments that glucose to bioethanol, so neither enzyme ever accumulates enough product to inhibit itself.","credit":"Team Mingdao, iGEM 2026 wiki"}]},{"id":"6108","team":"GU Frankfurt","section":"Overgrad","country":"Germany","village":"Therapeutics","wiki":"https://2026.igem.wiki/gu-frankfurt/","rank":143,"awards":["Top 10 (Overgrad)","Best Part Collection — Winner (Overgrad)","Best Software — Nominee (Overgrad)","Best Education — Winner (Overgrad)","Best Presentation — Nominee (Overgrad)","Best Therapeutics Project — Nominee"],"projectTitle":"HIDE","tagline":"Hiding a transplanted organ from the immune system instead of suppressing the immune system","summary":"Around 183,000 transplants a year are followed by lifelong immunosuppression, which protects the graft by weakening the whole patient. HIDE attacks the cause instead: a synNotch receptor carrying a computationally designed binder recognises the donor organ's mismatched HLA class I alleles, triggers production and export of shRNA in extracellular vesicles, and silences only those 'non-self' HLAs by RNA interference, leaving the rest of the immune system intact. Three research fields are bridged at once (synNotch, RNAi, exosome delivery), with the binder and the shRNA both designed in silico by the dry lab and validated by FACS, qPCR, western blot and nanoparticle tracking analysis. It won Best Part Collection and Best Education because the by-products are as usable as the therapy: HUSH, an open-source RNAi design framework for polymorphic gene families, and TRUST, a framework for communicating about death and grief that iGEM did not previously have.","images":[{"url":"https://static.igem.wiki/teams/6108/wiki/images/drylab/hush/hush-1-input-page.avif","caption":"HUSH step one: the target sequence to silence plus an optional panel of related alleles to spare, with live input inspection reporting molecule type, length, GC content and readiness, and warning when a GC-rich target may defeat the seed filter.","credit":"Team GU Frankfurt, iGEM 2026 wiki"}]},{"id":"6110","team":"TU Delft","section":"Overgrad","country":"Netherlands","village":"Biomanufacturing","wiki":"https://2026.igem.wiki/tu-delft/","rank":289,"awards":["Grand Prize Winner (Overgrad)","Top 10 (Overgrad)","Best Model — Nominee (Overgrad)","Best Presentation — Nominee (Overgrad)","Best Wiki — Winner (Overgrad)","Best Integrated Human Practices — Winner (Overgrad)","Best Entrepreneurship — Nominee (Overgrad)","Best Biomanufacturing Project — Winner"],"projectTitle":"MOSAIC","tagline":"A modular elastin-like polypeptide coating platform that lets one implant surface be tuned to the tissue, and the patient, it sits in.","summary":"MOSAIC is a modular implant coating built from elastin-like polypeptides (ELPs) that can be swapped part by part so a single platform serves many implants and tissues. The team's insight is that an implant coating has to match the stiffness and biochemistry of its target tissue: tissue stiffness spans 0.1 kPa in brain to over 1 MPa in bone, while titanium is around 100 GPa, so a one-size coating gives cells the wrong signal. They built five linked models to steer design before the lab work - an XGBoost predictor of ELP transition temperature, coarse-grained molecular dynamics of the surface-tethered hydrogel, an omics pipeline turning transcriptomic and proteomic atlases into tissue-specific coating recipes, a SuperPro Designer scale-up of ELP manufacturing, and a life-cycle assessment of that process - and they ran Value Sensitive Design across 13 interviews so stakeholders shaped the construct while it could still change. It took the Overgrad Grand Prize along with Best Wiki, Best Integrated Human Practices and Best Biomanufacturing Project.","images":[{"url":"https://static.igem.wiki/teams/6110/wiki/software/workflow.avif","caption":"What the MOSAIC Designer takes over: from a researcher's amino acid sequence through part identification, codon scrambling, Golden Gate cut-site design and synthesis feasibility checks to order-ready library sequences.","credit":"Team TU Delft, iGEM 2026 wiki"}]},{"id":"6115","team":"BNDS-China","section":"High School","country":"China","wiki":"https://2026.igem.wiki/bnds-china/","rank":14,"awards":["Best Education — Nominee (High School)","Best Wiki — Nominee (High School)"],"projectTitle":"OrbitColi","tagline":"An AND-logic-gate engineered probiotic that senses oxidative stress in space and produces vitamin B2 and trehalose to protect astronauts","summary":"BNDS-China built OrbitColi, an engineered E. coli probiotic designed to sense oxidative conditions arising from cosmic radiation and microgravity and respond by producing vitamin B2 and trehalose, replacing fixed-dose supplements that degrade over multi-year missions. The scientific framing is quantitative: ISS crews receive 100-200 mSv per year against a 20 mSv occupational limit, and a three-year Mars round trip may accumulate 300-450 mSv. The team's distinguishing contribution is methodological: they invented and applied a five-step education framework, R.E.A.C.H. (Recognize, Experience, Apply, Communicate, Harvest), to every single outreach activity, with a pre-event diagnostic survey and a matched post-event survey, and they report their own failures against it. Integrated Human Practices used a parallel STAR framework (Scan, Test, Assemble, Reflect) across five cycles.","images":[{"url":"https://static.igem.wiki/teams/6115/wiki/edu/image20.webp","caption":"Kindergarten children with the BioBrick 'building block' constructs they assembled in small 'syndicates'","credit":"Team BNDS-China, iGEM 2026 wiki"}]},{"id":"6119","team":"UMA Malaga","section":"Undergrad","country":"Spain","village":"Diagnostics","wiki":"https://2026.igem.wiki/uma-malaga/","rank":21,"awards":["Best Alternative Platform — Nominee (Undergrad)","Best Software — Nominee (Undergrad)","Best Diagnostics Project — Nominee"],"projectTitle":"Frida","tagline":"A SHERLOCK-type LwCas13a screen for rare-disease variants, with Diana, a tool that takes a disease name all the way to a plate map.","summary":"Frida uses CRISPR/LwCas13a (SHERLOCK-type collateral cleavage read as fluorescence) to screen for the mutations behind rare genetic diseases, with cystic fibrosis as the model disease and a tandem gRNA assembly system (Neith) for multiplexing. Because a single disease can have hundreds of pathogenic variants and each needs its own guide, the team built Diana (diana-grna-designer), a free MIT-licensed web app, command-line tool and F# library that goes from a disease name, OMIM number or MONDO id, through ClinVar's variant list, to ranked and scored guide RNAs, to an order-ready oligo list, to a combinatorial pooling plan and a decoder for the positive wells. The engineering is unusually disciplined for iGEM: 1,164 unit and component tests plus 75 Playwright browser tests, automated axe-core WCAG 2.2 AA accessibility scans of every page state, every dependency pinned and checksum-verified, and exports in GenBank, SBOL 3 and SBOL 2 that are read back by Biopython and pySBOL3 as part of the test suite. Most striking, the wet lab contradicted the software's central heuristic and the team published that: the synthetic-mismatch substitution rule did not discriminate alleles in the placements tried, so the rule became an option to compare rather than a promise.","images":[{"url":"https://static.igem.wiki/teams/6119/wiki/images/software/v6-07-builder-ranked-table.avif","caption":"Diana's ranked spacer table: GC score, homopolymers, off-targets, assembly compatibility badges, folding energy, unpaired spacer share, mismatches against the other allele and the relative score, with the seed underlined and the mutation in red.","credit":"Team UMA Malaga, iGEM 2026 wiki"}]},{"id":"6122","team":"Cornell","section":"Undergrad","country":"United States","village":"Fashion & Cosmetics","wiki":"https://2026.igem.wiki/cornell/","rank":155,"awards":["Top 10 (Undergrad)","Best Hardware — Winner (Undergrad)","Best Education — Nominee (Undergrad)","Best Presentation — Winner (Undergrad)","Best Fashion & Cosmetics Project — Winner"],"projectTitle":"Klothos","tagline":"A smart bandage: engineered probiotics inside electrospun alginate nanofibers that release an anti-fibrotic peptide only where a wound is scarring badly.","summary":"Every scar treatment on the market today starts after the scar has formed — silicone sheeting, intralesional steroid, laser and grafts are all passive or reactive, and none addresses fibrosis biology during the critical healing window. Klothos intervenes during healing instead: engineered bacteria secrete 810A, a 12-amino-acid peptide that binds the exposed C-terminal domain of CTGF (CCN2) and blocks fibroblast-to-myofibroblast activation, and expression is held behind a two-input AND gate built from the Pseudomonas syringae hrpR/hrpS/hrpL system so the peptide is only made when reactive oxygen species (via TrxC) and hypoxia (via Pfnr) are both present — the signature of unchecked remodelling. The bacteria are encapsulated in an alginate/PEO nanofiber matrix spun on a coaxial electrospinner the team designed and built themselves, because commercial instruments cost far more than an undergraduate team can reach. It won Best Hardware and Best Presentation on the strength of that open, flat-packable, interlock-protected electrospinner plus a modular 3D-printed coaxial spinneret adapter, and Best Fashion & Cosmetics on a project that is unusually complete end to end: 20-plus risk-rated commercialisation analysis, a six-phase FDA path, and a human practices programme built around people who actually live with scars.","images":[{"url":"https://static.igem.wiki/teams/6122/wiki/modeling/productdev-14-spinning-viability-alginate-peo-classifier-map.avif","caption":"Predicted spinning viability across sodium alginate and PEO weight percentages, generated by Monte Carlo sampling over the viscosity, conductivity and surface tension models — the map behind the green/yellow/red readiness classifier that decides whether a formulation reaches the electrospinner.","credit":"Team Cornell, iGEM 2026 wiki"}]},{"id":"6124","team":"Madrid-UCM","section":"Undergrad","country":"Spain","village":"Bioremediation","wiki":"https://2026.igem.wiki/madrid-ucm/","rank":21,"awards":["Best Sustainable Development Impact — Nominee (Undergrad)","Best Entrepreneurship — Nominee (Undergrad)","Best Bioremediation Project — Nominee"],"projectTitle":"rePhlow: A modular synthetic-biology platform for phosphorus capture and valorisation from industrial wastewater","tagline":"Phosphorus should not reach nature as pollution, and it should not leave industry as waste.","summary":"rePhlow intercepts phosphorus in a defined industrial wastewater stream rather than attempting to 'solve eutrophication'. An immobilised enzyme panel (phosphatases, phospholipases, phytase) releases phosphorus from organic and condensed fractions; engineered Pseudomonas putida KT2440 carrying heterologous ppk1 and the Accumulibacter Pst high-affinity transport system, with pitB/ppx/ppkB knocked out by CRISPR base editing, accumulates it as polyphosphate inside core-shell alginate-chitosan capsules; the recovered polyP then feeds a coupled PPK2/DHAK biocatalytic cascade producing dihydroxyacetone phosphate. The capsules sit in a basket-type rotating-bed bioreactor the team built themselves, with encapsulation doubling as the EU contained-use regulatory strategy. The project is explicitly framed as a two-sided business: paid to remove phosphorus, paid again for the phosphorus recovered.","images":[{"url":"https://static.igem.wiki/teams/6124/wiki/assets/human-practices/travel-archive/bio-oils-01.webp","caption":"The Bio-Oils Huelva biodiesel plant, whose degumming effluent ranges became rePhlow's semi-synthetic test stream and later its first real sample.","credit":"Team Madrid-UCM, iGEM 2026 wiki"}]},{"id":"6133","team":"GreatBay-SCIE","section":"High School","country":"China","wiki":"https://2026.igem.wiki/greatbay-scie/","rank":47,"awards":["Best Model — Nominee (High School)","Best Integrated Human Practices — Nominee (High School)","Inclusivity Award — Winner (High School)","Best Village Project — Nominee (Agriculture / Food & Nutrition / Fashion & Cosmetics / Art & Design)"],"projectTitle":"Expelliodor — Expel the Odor, on Your Terms","tagline":"Three de novo designed proteins that stop axillary odour before it forms, without killing the skin microbiome.","summary":"Axillary odour arises when Staphylococcus hominis imports the odourless precursor Cys-Gly-3M3SH through the peptide transporter PepTSh and converts it to 3M3SH. Rather than killing skin bacteria, GreatBay-SCIE attacked the uptake step three ways: a de novo small-molecule binding protein that sequesters the precursor, a de novo protein binder designed to lock PepTSh in its inward-facing conformation, and a cyclodextrin glucanotransferase engineered to glycosylate the precursor so the transporter no longer recognises it. This is the most sophisticated de novo protein design campaign of any high school team in the cohort — RFdiffusion3, Proteina-Complexa, ProteinMPNN, RoseTTAFold3 co-folding, 50-ns MD with MM/GBSA, and SPURS-guided thermostability engineering — organised around two frameworks they invented: a Characterize stage prepended to DBTL, and a funnel-shaped decision-gated workflow that spends expensive methods only on candidates that survive cheap ones. Nine precursor binders and five transporter binders were actually tested in vitro, with 4 of 9 and 4 of 5 significantly reducing 3M3SH.","images":[{"url":"https://static.igem.wiki/teams/6133/wiki/drylab/model/overview-fig3.avif","caption":"The funnel-shaped decision-gated workflow: successive evaluation gates remove designs from a large generated space until a small testing set remains, with each gate more computationally expensive than the last. Designed explicitly so a high school team with limited wet-lab resources spends molecular dynamics time only on candidates that already survived cheap co-folding filters.","credit":"Team GreatBay-SCIE, iGEM 2026 wiki"}]},{"id":"6145","team":"MIT-MAHE","section":"Undergrad","country":"India","village":"Food & Agriculture / Manufacturing","wiki":"https://2026.igem.wiki/mit-mahe/","rank":33,"awards":["Best Software — Nominee (Undergrad)","Inclusivity Award — Winner (Undergrad)"],"projectTitle":"MAHEK","tagline":"Sustainable cuminaldehyde from Pseudomonas putida, and NetFlux, a web tool that turns a genome-scale metabolic model into a drawable pathway and a ranked list of knockouts.","summary":"MAHEK addresses the fragrance industry's dependence on petrochemical synthesis and wasteful seed extraction by producing cuminaldehyde biologically. The chassis is Pseudomonas putida F1, a solvent-tolerant soil bacterium that already makes cuminaldehyde as an intermediate in p-cymene degradation; CRISPR-Cas9-mediated homologous recombination knocks out cymC, the p-cumic aldehyde dehydrogenase, arresting the pathway exactly at the target compound. The dry lab's deliverable is NetFlux, a React + FastAPI web application that compresses a genome-scale metabolic model into a readable 'production corridor' using a novel extraction algorithm (SCOPE) and then pools OptKnock and OptForce into one co-ranked list of knockout and regulation strategies, each traced to the gene and linked to BiGG. The team also won the Inclusivity Award for work with visually impaired learners that ended in Vision Empower adopting their tactile models for use in schools across India.","images":[{"url":"https://static.igem.wiki/teams/6145/wiki/dry-lab/software/fig-2-architecture.avif","caption":"NetFlux architecture: React/TypeScript frontend, FastAPI backend with Pydantic schemas and a bounded JobManager worker pool, over a SQLite model catalogue and precomputed Mass Flow Graphs.","credit":"Team MIT-MAHE, iGEM 2026 wiki"}]},{"id":"6151","team":"Uni-Padua-IT","section":"Undergrad","country":"Italy","village":"Space","wiki":"https://2026.igem.wiki/uni-padua-it/","rank":59,"awards":["Best Software — Winner (Undergrad)","Best Wiki — Winner (Undergrad)","Best Space Project — Nominee"],"projectTitle":"C.O.S.M.I.C. (Cyanobacterial Oxygen Supply for Martian Inhabitant Complexes)","tagline":"A Nostoc-based life-support chassis for Mars, plus ReTIsigner, an open codon optimiser for the 35,799 hosts other tools ignore.","summary":"Uni-Padua-IT engineered the filamentous cyanobacterium Nostoc sp. PCC 7120 as a Martian life-support organism: it fixes CO2 into breathable oxygen, degrades the perchlorates that poison Martian water (via native NarB and a heterocyst-compartmentalised pcrABD plus chlorite dismutase), and carries pprA from Deinococcus radiodurans for radiation-damage repair, behind a copper-dependent MazF kill switch. Because no free codon optimiser listed their chassis, they forked TIsigner into ReTIsigner, a frequency-weighted codon optimiser that reads any of the 35,799 Kazusa codon usage tables, enforces GC bounds, actively excises RFC restriction sites and reports CAI, GC and translation-initiation opening energy. ReTIsigner was validated in silico over 100 sequences and four hosts, then in vivo: a ReTIsigner-optimised eYFP gave a 2.16-fold common-effect increase in specific fluorescence across DH5-alpha and BL21 (p = 0.002, permutation test stratified by strain). They also built an open-source acoustic (piezo + Arduino) bubble sensor so oxygen production can be followed without opening a sealed culture.","images":[{"url":"https://static.igem.wiki/teams/6151/wiki/software/new-frontend.avif","caption":"The ReTIsigner interface the team built from scratch in SvelteKit, replacing the original TIsigner form.","credit":"Team Uni-Padua-IT, iGEM 2026 wiki"}]},{"id":"6157","team":"UCAS-China","section":"Undergrad","country":"China","village":"Therapeutics","wiki":"https://2026.igem.wiki/ucas-china/","rank":212,"awards":["1st Runner-up (Undergrad)","Top 10 (Undergrad)","Best New Composite Part — Nominee (Undergrad)","Best Wiki — Nominee (Undergrad)","Best Integrated Human Practices — Winner (Undergrad)","Best Therapeutics Project — Nominee"],"projectTitle":"PARCEL","tagline":"An inhaled, protein-based mRNA carrier that makes airway cells produce their own asthma medicine.","summary":"PARCEL is an inhaled mRNA delivery platform built from elastin-like polypeptides (ELPs) rather than lipid nanoparticles. The fusion protein ELP-Pum2-EEP13 uses Pum2 to grab mRNA carrying a PRS tag in its 3' UTR, ELP phase separation to encapsulate and protect it, an endosomal escape peptide to get out of the endosome, and a Sortase A-conjugated anti-UPK1B scFv to target airway club cells; the cargo is mRNA for SLPI (inhibiting neutrophil elastase and the mucus hypersecretion it triggers) plus a lower dose of IFN-lambda-1 (antiviral defence and Th2 suppression). It won 1st Runner-up and Best Integrated Human Practices because the stakeholder work genuinely steered the science: clinicians moved the project from rescue therapy to maintenance therapy, and an asthma mechanism researcher killed one of the two original cargoes outright. The dry lab is unusually complete, modelling the whole chain from E. coli production through nebulizer aerosol deposition to a PK-PD readout in FEV1 and FeNO, with every module feeding the next.","images":[{"url":"https://static.igem.wiki/teams/6157/wiki/humanpractices/hp-overview0.avif","caption":"The Human Practices overview: 20 individuals and institutions across six defined communities, 44 asthma patient representatives and 419 public representatives, mapped onto nine project iterations of the team's own RCSF cycle.","credit":"Team UCAS-China, iGEM 2026 wiki"}]},{"id":"6158","team":"HongKong-JSS","section":"High School","country":"Hong Kong","village":"Agriculture","wiki":"https://2026.igem.wiki/hongkong-jss/","rank":219,"awards":["1st Runner-up (High School)","Top 10 (High School)","Best New Composite Part — Nominee (High School)","Best Model — Nominee (High School)","Best Hardware — Nominee (High School)","Best Presentation — Nominee (High School)","Best Village Project — Winner (Agriculture / Food & Nutrition / Fashion & Cosmetics / Art & Design)"],"projectTitle":"MerMAID - MerR-based Mercury Assay for In-field Detection","tagline":"One mercury ion among a billion molecules of water - a living sensor that glows red, read by a portable detector fed by a modular sample-extraction platform.","summary":"HongKong-JSS is a four-school joint team (Y.W.C.A. Hioe Tjo Yoeng College, Po Leung Kuk Celine Ho Yam Tong College, Pentecostal School, Yan Oi Tong Tin Ka Ping Secondary School) that built a complete mercury-screening system for agricultural water and soil: a MerR-regulated E. coli biosensor expressing mRFP1e, a portable modular fluorescence reader, and a motorised sample-extraction platform that turns soil and water into a standard assay input. They designed, built and tested 13 biosensor prototypes - 2 aptamer-based and 11 protein-based - of which two protein designs responded to Hg2+, with the best showing low background, a response down to about 1 ppb (0.005 uM, roughly sixfold below the WHO drinking-water guideline of 6 ug/L), no cross-response to Cd2+, Pb2+ or Zn2+ at the concentrations tested, and retained function after alginate encapsulation. It took 1st Runner-up Grand Prize in the High School section and won Best Village Project, and the reason is visible on every page: the wiki's standing rule is that every number carries its conditions and a source, and the team separates demonstrated results from deployment claims more rigorously than most university teams.","images":[{"url":"https://static.igem.wiki/teams/6158/wiki/model/figure-1.avif","caption":"Control-subtracted colour and pellet-fluorescence signals against log mercury concentration, with each calibration run coloured separately and the pooled log-linear fit overlaid.","credit":"Team HongKong-JSS, iGEM 2026 wiki"}]},{"id":"6165","team":"SMS-Shenzhen","section":"High School","country":"China","village":"Climate Crisis / Conservation / Bioremediation (inferred from project scope; no village stated on the wiki)","wiki":"https://2026.igem.wiki/sms-shenzhen/","rank":7,"awards":["Best New Composite Part — Nominee (High School)"],"projectTitle":"kisMET - selective biosorption of residual metals from battery-recycling wastewater","tagline":"Catching the last one percent of lithium, cobalt, nickel and manganese without more chemistry","summary":"kisMET targets the tail-end wastewater of spent lithium-ion battery recycling, where metal concentrations fall to parts-per-million and solvent extraction stops being economic. The team engineered Komagataeibacter rhaeticus to decorate its own bacterial cellulose with a secreted fusion protein built from a signal peptide, a carbohydrate-binding module, a HiBiT reporter tag and a swappable ion-binding peptide, assembled by Golden Gate on a pSEVA331 backbone under a rhamnose-inducible promoter. Four SP/CBM scaffolds and an eight-member ion-binding-peptide panel were designed so the binding specificity can be changed without redesigning the platform. Evidence so far covers cultivation, construct and reporter comparisons, single-metal binding experiments and cellulose-degradation assays; the team states clearly that selectivity in mixed wastewater, closed-loop cellulose reuse and complete metal recovery are design objectives, not results.","images":[{"url":"https://static.igem.wiki/teams/6165/wiki/description-fig3-ibp-swap.avif","caption":"Molecular design of the pSEVA331 expression system, showing the interchangeable ion-binding-peptide modules that let the platform be retargeted to a different metal without redesign.","credit":"Team SMS-Shenzhen, iGEM 2026 wiki"}]},{"id":"6166","team":"GHCIS","section":"High School","country":"China","village":"Climate Crisis, Conservation & Bioremediation","wiki":"https://2026.igem.wiki/ghcis/","rank":136,"awards":["Top 10 (High School)","Best Part Collection — Winner (High School)","Best Software — Winner (High School)","Best Wiki — Nominee (High School)","Best Village Project — Nominee (Climate Crisis / Conservation / Bioremediation)"],"projectTitle":"ARGUS","tagline":"A paper-based toehold-switch assay plus a browser-based image-analysis and surveillance platform for environmental antimicrobial resistance gene monitoring.","summary":"ARGUS pairs a cell-free, paper-based toehold switch assay for three antimicrobial resistance genes (mcr-1, blaNDM-1, blaKPC-2) with portable temperature-control hardware and a full-stack web platform that reads the colorimetric plate from a phone photo, grades each gene, and stores location-linked records for regional review. Recombinase polymerase amplification feeds trigger RNA to switches that drive colour-producing enzymes — blue for MCR1 (GusA), yellow for NDM1 (XylE), purple-shifted for KPC2 (LacZ). The project is framed inside the One Health approach, targeting the gap between institution-led metagenomic surveys and the routine, fine-grained environmental monitoring that networks like CARSS do not cover. It won Best Software and Best Part Collection on the strength of a genuinely deployable platform (Docker or native Node, SQLite, role-based access, documented deployment) and a NUPACK design pipeline that reproduced a published sequence grammar and then found an error in it — all presented with an unusually disciplined limitations section that refuses to claim sensitivity, specificity or a detection limit it has not measured.","images":[{"url":"https://static.igem.wiki/teams/6166/wiki/software/figure-02.avif","caption":"ARGUS feature map: client functions (location, plate photographs, local four-grade analysis, personal records), console functions (regional review, alerts, exports), account management and operations.","credit":"Team GHCIS, iGEM 2026 wiki"}]},{"id":"6174","team":"Hongwen School","section":"High School","country":"China","wiki":"https://2026.igem.wiki/hongwen-school/","rank":21,"awards":["Best Hardware — Nominee (High School)","Best Sustainable Development Impact — Nominee (High School)","Best Village Project — Nominee (Agriculture / Food & Nutrition / Fashion & Cosmetics / Art & Design)"],"projectTitle":"BrewXOS","tagline":"Creating additional value within an existing spent-grain economy: brewer's spent grain to candidate arabinoxylan oligosaccharides.","summary":"Hongwen School (Shanghai and Qingdao) engineered Bacillus subtilis WB600 to secrete xylan-degrading enzymes that convert the arabinoxylan fraction of brewer's spent grain (BSG) into candidate arabinoxylan oligosaccharides (AXOS). Five strains - single Xyn2 and Xyn11A, two dual combinations with the GH62 arabinofuranosidase Abf62A, and a triple construct - were compared; the triple strain reached 257.10 +/- 5.55 U/mL apparent supernatant activity and a parental-adjusted index of 107.91 +/- 6.64 mg xylose equivalents per gram dry BSG after 12 h, 32.8% above the better dual strain. Alongside this they built BrewXOS Fermenter Mini, a small fermentation-monitoring prototype with a main-cap/sub-cap lid, headspace O2/CO2 sensing and a touchscreen interface, and tested it with real users. The Human Practices work is the best part of the project: a GRAIN x TRACE framework forces every stakeholder interaction to end in a named change plus the evidence for it, or be flagged as an open loop.","images":[{"url":"https://static.igem.wiki/teams/6174/wiki/public/hp/integration-pathway.webp","caption":"The GRAIN x TRACE integration pathway: how stakeholder input reshaped problem definition, purpose, scientific design, implementation strategy and knowledge sharing, with TRACE recording each question-to-change-to-evidence loop.","credit":"Team Hongwen School, iGEM 2026 wiki"}]},{"id":"6177","team":"SEHS","section":"High School","country":"China","village":"Therapeutics / health (inferred from project scope; no village stated on the wiki)","wiki":"https://2026.igem.wiki/sehs/","rank":7,"awards":["Best Alternative Platform — Nominee (High School)"],"projectTitle":"FusionDrive - an anti-TIGIT-IL-2v fusion protein for gastric cancer immunotherapy","tagline":"Release the immune brake and bias the accelerator, in one molecule","summary":"Starting from the high gastric-cancer burden in their home province of Shandong, SEHS designed FusionDrive, a fusion protein joining an anti-TIGIT antibody to an engineered IL-2 variant through a G4S linker. The antibody Fab blocks CD155-TIGIT inhibitory signalling to reverse T-cell exhaustion, while the Fc-fused IL-2v carries a low-alpha/high-beta modification that reduces CD25 binding and so biases stimulation away from regulatory T cells. Across five DBTL cycles the team built the antibody, the wild-type IL-2 fusion and the variant fusion in CHO cells and compared them by SDS-PAGE, TIGIT-binding ELISA (EC50 0.6317 nM for the antibody, 1.335 nM after IL-2 fusion) and flow cytometry for CD25 and pSTAT5. Because the iGEM high-school White List left Jurkat as the only available T-cell line, they used PHA induction to create CD25-high and CD25-low populations as a stand-in for the Treg receptor phenotype.","images":[{"url":"https://static.igem.wiki/teams/6177/wiki/description/fig-03.avif","caption":"From design to initial validation: the five engineering cycles taking FusionDrive from anti-TIGIT antibody to wild-type IL-2 fusion to the low-alpha/high-beta IL-2 variant fusion.","credit":"Team SEHS, iGEM 2026 wiki"}]},{"id":"6178","team":"HFI","section":"High School","country":"China","village":"Therapeutics","wiki":"https://2026.igem.wiki/hfi/","rank":143,"awards":["Top 10 (High School)","Best Part Collection — Nominee (High School)","Best Education — Winner (High School)","Best Presentation — Nominee (High School)","Best Wiki — Nominee (High School)","Best Village Project — Winner (Infectious Diseases / Therapeutics / Diagnostics / Oncology)"],"projectTitle":"TWO EcN, ONE METABOLIC MISSION - A Probiotic Synergistic Therapy for the Rare Disease Hyperlysinemia","tagline":"A dual-strain E. coli Nissle 1917 consortium, physically stapled together with SpyTag/SpyCatcher, that degrades dietary lysine in the gut so hyperlysinemia patients can escape lifelong diet restriction.","summary":"HFI (International Department, The Affiliated High School of South China Normal University, Guangzhou) built an orally delivered live biotherapeutic for hyperlysinemia, a rare AASS-mutation disorder with no approved therapy and an incidence near 1 in 411,000. They split the human saccharopine pathway across two EcN populations - an upstream strain expressing LKR and SDH, a downstream strain expressing ALDH and AASDHPPT - knocked out the endogenous ldcC lysine decarboxylase by CRISPR-Cas9 to remove background lysine consumption, and covalently coupled the two strains using eCPX-displayed SpyTag/SpyCatcher so intermediates pass between cells over a short diffusion distance. Biosafety is handled by a dual-input kill switch where an arabinose-driven Bxb1 serine integrase inverts the lysis-E cassette and an oxygen-sensing PcyoA promoter only fires outside the anaerobic gut. The project won because the dry lab genuinely steered the wet lab (NetLogo screening picked the RBS before cloning), the part collection was fully characterised with HPLC-MS, and the education and IHP programmes were unusually systematic for a high school team.","images":[{"url":"https://static.igem.wiki/teams/6178/wiki/model/4.avif","caption":"NetLogo agent-based output: simulation trajectories (A) and cluster-size distributions (B) under different SpyCatcher binding capacities, showing the transition from fragmented association at low display to near-global condensation at 50+ sites.","credit":"Team HFI, iGEM 2026 wiki"}]},{"id":"6185","team":"Lambert-GA","section":"High School","country":"United States","village":"Conservation","wiki":"https://2026.igem.wiki/lambert-ga/","rank":301,"awards":["Grand Prize Winner (High School)","Top 10 (High School)","Best Model — Winner (High School)","Best Hardware — Nominee (High School)","Best Wiki — Winner (High School)","Best Sustainable Development Impact — Winner (High School)","Best Village Project — Winner (Climate Crisis / Conservation / Bioremediation)"],"projectTitle":"SWARM - de novo minibinders against Deformed Wing Virus paired with multiplexed RNAi against Varroa destructor","tagline":"Protecting honeybees by hitting both the virus and the mite that carries it, with the first reported minibinder confirmed to bind DWV's VP3.","summary":"Lambert iGEM (Suwanee, Georgia) built SWARM to attack the two linked causes of honeybee colony collapse: Deformed Wing Virus and the Varroa destructor mite that vectors it. US beekeepers reported losing 55.6% of managed colonies between April 2024 and April 2025, and Georgia's large operations lost roughly 88,000 colonies in nine months. SWARM pairs a computationally designed 79-amino-acid minibinder against the exposed P-domain of DWV's VP3 capsid protein - experimentally confirmed by biolayer interferometry at KD = 603.6 nM (95% CI 497.1-733.3 nM), to the team's knowledge the first reported minibinder with confirmed binding to VP3 - with a multiplexed dsRNA construct silencing three Varroa salivary-gland genes (Vd-CHIsal, Vd-CHIBIN, VdAV422) at once to blunt resistance. Both components are delivered through feeding practices beekeepers already use. They took the High School Grand Prize plus Best Model, Best Wiki, Best Sustainable Development Impact and Best Village Project, and the modelling is the headline: four linked models spanning protein design benchmarking on 5,721 experimentally labelled designs, oral pharmacokinetics with Sobol sensitivity analysis, a 13-ODE RNAi network, and an individual-based six-year colony epidemiology simulation across two climates.","images":[{"url":"https://static.igem.wiki/teams/6185/wiki/modeling/img-6251.avif","caption":"The epidemiological model pipeline: how minibinder protection (assigned per bee from its syrup intake) and RNAi exposure at brood capping enter the individual-based colony simulation.","credit":"Team Lambert-GA, iGEM 2026 wiki"}]},{"id":"6187","team":"Toronto","section":"Overgrad","country":"Canada","village":"Bioremediation","wiki":"https://2026.igem.wiki/toronto/","rank":124,"awards":["Top 10 (Overgrad)","Best Model — Winner (Overgrad)","Best Hardware — Nominee (Overgrad)","Best Wiki — Nominee (Overgrad)","Best Entrepreneurship — Nominee (Overgrad)","Best Bioremediation Project — Nominee"],"projectTitle":"PetaBite","tagline":"Planetary-scale bioprospecting for plastic-degrading enzymes: mine 300M candidates, then match an enzyme to each real-world condition.","summary":"PetaBite attacks PET and microplastic pollution by abandoning the field's usual strategy of engineering a handful of known enzymes and instead searching the natural sequence landscape at planetary scale. The dry lab rebuilt PETadex from scratch into PETadex V2: 1.74 billion plastic-degrading enzyme homologs recovered from NCBI nr and the Logan assembly of the entire Sequence Read Archive, filtered by 53 hand-curated catalytic HMMs to 291,922,243 complete catalytic ORFs, each annotated with the pH, temperature, salinity and environment of the sample it came from. They paired this with PETai activity labels scraped from literature by an LLM pipeline and by 20+ human curators, pretrained PlasticESM (LoRA adapters on ESM-C) on the corpus, and built a hardware bioreactor array to feed condition-specific measurements back into the model. They won Best Model largely for scientific honesty: a homology-component-grouped split showed that sequence length beats their own embeddings, and they reported that rather than the inflated random-split numbers.","images":[{"url":"https://static.igem.wiki/teams/6187/wiki/drylab-page/figures/petadex-workflow-overview.svg","caption":"Overview of the PETadex V2 discovery pipeline: curated PAZy enzymes seed catalytic HMMs, which mine NCBI nr and the Logan SRA assembly down to 291,922,243 complete catalytic ORFs.","credit":"Team Toronto, iGEM 2026 wiki"}]},{"id":"6196","team":"TAU-Israel","section":"Overgrad","country":"Israel","village":"Therapeutics / Foundational Advance","wiki":"https://2026.igem.wiki/tau-israel/","rank":7,"awards":["Best Software — Nominee (Overgrad)"],"projectTitle":"CERNAL","tagline":"A biological compiler: supply RNA expression data, get ranked RNA logic-gate circuit designs that fire only in the cell state you specify.","summary":"CERNAL treats the transcriptome as a fingerprint of cellular state and compiles that fingerprint into an RNA logic circuit: it picks the transcripts that distinguish a target cell from its neighbour, scans each transcript for an accessible, unique, constructible trigger window, designs a toehold-style switch whose hairpin hides the ribosome binding site until that trigger unzips it, combines switches into AND and NOT gates, ranks every candidate on shared thermodynamic metrics, and assembles the winner into an annotated plasmid. Because the sensing element is the cell's own RNA rather than a characterised transcription factor, the approach is intended to be host-agnostic, and the team demonstrated it in three proofs of concept: endometriosis logic in HEK293T, a PFOA/PFAS biosensor in E. coli, and CRISPRa gates in yeast. The software is a Django Ninja + React 19 application with a strictly isolated scientific engine, a versioned HTTP API with Python, R and MATLAB clients, SBOL 3 export, and an IBBIS Common Mechanism biosecurity gate that withholds sequence files when screening cannot be completed. The team filed a provisional patent through Tel Aviv University's TTO and built a full market case around cell and gene therapy developers.","images":[{"url":"https://static.igem.wiki/teams/6196/wiki/software/01-inputs.avif?v=4","caption":"CERNAL's Inputs panel: E. coli selected as host and a 711-nucleotide mCherry transcript entered as a Direct Trigger mRNA, from the recorded five-step walkthrough.","credit":"Team TAU-Israel, iGEM 2026 wiki"}]},{"id":"6197","team":"HangzhouFourteenAP","section":"High School","country":"China","village":"Space, Foundational Advance, Software & AI, Biomanufacturing","wiki":"https://2026.igem.wiki/hangzhoufourteenap/","rank":124,"awards":["Top 10 (High School)","Best Measurement — Nominee (High School)","Best Presentation — Nominee (High School)","Best Wiki — Nominee (High School)","Best Integrated Human Practices — Nominee (High School)","Best Village Project — Winner (Space / Foundational Advance / Software & AI / Biomanufacturing)"],"projectTitle":"DCO (Dental Calculus Obstructor)","tagline":"A four-enzyme cocktail plus a hydroxyapatite-binding antimicrobial peptide coating that dismantles dental plaque biofilm before it mineralises into calculus.","summary":"DCO is a three-module biological oral care system: an enzyme cocktail that degrades the organic matrix holding plaque biofilm together, a tooth-binding antimicrobial peptide that coats enamel to block re-colonisation, and a controlled-release system to coordinate them. The enzymes are two recombinantly expressed glycoside hydrolases — PmGH87 (alpha-1,3-glucanase) and CoGH66 (alpha-1,6-glucanase), which act cooperatively because CoGH66 removes alpha-1,6 branches and exposes new PmGH87 cleavage sites — plus commercially sourced DNase I and papain for extracellular DNA and protein. It addresses a real and specific burden: 96.7% of Chinese adults aged 35-44 have dental calculus, over 900 million have periodontal disease, only 20.1% of elderly people saw a dentist in the past year, and the dentist-to-population ratio is about 1:7,768. It won Best Village Project on a tight problem-to-product chain, a FoldX mutation-prioritisation pipeline whose prediction was wrong and whose failure is reported in full, and an unusually commercially literate entrepreneurship section that refuses to make anti-calculus claims it cannot support.","images":[{"url":"https://static.igem.wiki/teams/6197/wiki/content/model/modeling-figure1.avif","caption":"The CoGH66 mutation prioritisation workflow: PyMOL contact identification in PDB 8IUB, mapping onto the MAFFT/ESPript conservation map to select substitutable sites, point mutation in PyMOL, and FoldX delta-delta-G calculation to rank candidates.","credit":"Team HangzhouFourteenAP, iGEM 2026 wiki"}]},{"id":"6199","team":"SUIS-SFLS","section":"High School","country":"China","wiki":"https://2026.igem.wiki/suis-sfls/","rank":7,"awards":["Best Entrepreneurship — Nominee (High School)"],"projectTitle":"TyroFix","tagline":"Recyclable magnetic-bead tyrosinase that cheaply DOPA-modifies recombinant mussel adhesive protein, sold as a B2B raw material","summary":"SUIS-SFLS expressed three microbial tyrosinases, immobilised them on magnetic beads so the enzyme can be magnetically recovered and reused, and used the recycled catalyst to hydroxylate Mfp3-linker-Mfp6 fusion mussel foot proteins into DOPA-bearing wet adhesives for skin and wound repair. The commercial thesis is unusually self-aware: after expert interviews they abandoned the idea of selling a finished dressing and repositioned as an upstream B2B raw-material supplier, splitting the same protein stock into TyroFix Mini (cosmetic grade) and TyroFix ProMax (Class II medical grade) and running both regulatory tracks in parallel from day one so that test data never has to be repeated. They are the only high-school team here with a genuine financial model, including capex, cost per litre, pricing, gross margin and breakeven year for each line, published as downloadable PDFs. They were nominated for Best Entrepreneurship in the High School section.","images":[{"url":"https://static.igem.wiki/teams/6199/wiki/entrepreneurship/figure-11.avif","caption":"Financial planning for TyroFix Mini: capex, R&D spend, CNY 71 per litre production cost and the volume ramp to 30,000 litres by year five","credit":"Team SUIS-SFLS, iGEM 2026 wiki"}]},{"id":"6214","team":"HongKong-HS","section":"High School","country":"Hong Kong","village":"Diagnostics","wiki":"https://2026.igem.wiki/hongkong-hs/","rank":84,"awards":["Top 10 (High School)","Best Wiki — Nominee (High School)","Best Village Project — Nominee (Infectious Diseases / Therapeutics / Diagnostics / Oncology)"],"projectTitle":"AmpliRen - a urine-based home screening kit concept for chronic kidney disease using urinary miRNA and hybridisation chain reaction","tagline":"Early signals. Made visible. A small sample telling a bigger story.","summary":"HongKong-HS is a five-school joint team (Wah Yan College Kowloon, Pope Paul VI College, C&MA Sun Kei Secondary School, Tsung Tsin Christian Academy, St. Paul's School Lam Tin) tackling chronic kidney disease, which affects roughly 788 million adults worldwide, has risen past 405,000 recorded adult cases in Hong Kong, and is usually caught only at stage 3-5 because creatinine-based eGFR does not move until about half of kidney function is gone. AmpliRen detects two urinary microRNAs - miR-21-5p for fibrosis severity and miR-192-5p as an early warning, together reported at 89% sensitivity and 82% specificity - and amplifies the signal enzyme-free at room temperature with hybridisation chain reaction, whose G-rich hairpin loops fold into G-quadruplexes that bind hemin to form a DNAzyme and oxidise TMB into a colour change visible in natural light. The project is a genuine four-cycle engineering story: the team started with toehold switches designed in miRADAR and screened in NUPACK, found EGFP output too weak and invisible, pivoted to HCR, then to G-quadruplex-containing probes, then to hemin/TMB colorimetry. It was nominated for Best Wiki on one of the most ambitious scroll-driven, 3D-visualised wikis in the competition.","images":[{"url":"https://static.igem.wiki/teams/6214/wiki/project/engineering/fig-10-complex-formation-of-toehold-7-for-mir-192-5p-nupack.avif","caption":"NUPACK equilibrium complex-formation analysis for toehold 7 against miR-192-5p; the red bars show the active toehold-miRNA complex concentration used to rank candidates alongside the HMFE-versus-TMFE comparison.","credit":"Team HongKong-HS, iGEM 2026 wiki"}]},{"id":"6222","team":"WageningenUR","section":"Overgrad","country":"Netherlands","village":"Bioremediation","wiki":"https://2026.igem.wiki/wageningenur/","rank":264,"awards":["1st Runner-up (Overgrad)","Top 10 (Overgrad)","Best Measurement — Winner (Overgrad)","Best Presentation — Winner (Overgrad)","Best Wiki — Nominee (Overgrad)","Best Integrated Human Practices — Nominee (Overgrad)","Best Entrepreneurship — Nominee (Overgrad)","Best Bioremediation Project — Winner"],"projectTitle":"Triton","tagline":"Capture, degrade and sense trifluoroacetate: a three-module biological system for the smallest forever chemical, aimed at reverse-osmosis concentrate.","summary":"Triton targets trifluoroacetate (TFA), the ultra-short-chain PFAS that makes up more than 98% of all PFAS measured in EU river and groundwater and was found in the blood of all 110 Europeans tested in a 2026 study. Rather than one trick, they built three modules shaped entirely by stakeholder input: a de novo protein binder on bacterial cellulose beads to concentrate TFA out of reverse-osmosis concentrate, a growth-coupled directed hyper-evolution platform to push fluoroacetate dehalogenases from monofluoroacetate toward difluoroacetate and then TFA, and a riboswitch biosensor for continuous on-site monitoring. The dry lab contributed two reusable tools - PIGEON, an active-learning in silico evolution loop that lifted a Boltz-2 binding probability by over 33%, and DISARM, which retargets existing aptamers to new small-molecule ligands without SELEX. They took 1st Runner-up Grand Prize plus Best Measurement, Best Presentation and Best Bioremediation Project.","images":[{"url":"https://static.igem.wiki/teams/6222/wiki/text-images/general/triton-wholesystem-v5.avif","caption":"The full Triton system: reverse-osmosis concentrate passes a bacterial-cellulose capture filter to concentrate TFA, then a bioreactor where evolved dehalogenase cleaves the C-F bond while a riboswitch biosensor monitors concentration continuously.","credit":"Team WageningenUR, iGEM 2026 wiki"}]},{"id":"6236","team":"ZQT-Nanjing","section":"High School","country":"China","village":"Biomanufacturing / sustainable production (inferred from project scope; no village stated on the wiki)","wiki":"https://2026.igem.wiki/zqt-nanjing/","rank":33,"awards":["Best New Composite Part — Nominee (High School)","Best Project Promotion Video — Winner (High School)"],"projectTitle":"EcToBloom","tagline":"A greener, low-salt route to ectoine, finished as a compostable bacterial-cellulose repair mask","summary":"EcToBloom rebuilds the ectoine biosynthesis route (ectB-ectA-ectC from halophilic bacteria) in non-halophilic E. coli BL21(DE3) so that ectoine can be made under conventional low-salt fermentation instead of the industrial high-salt 'bacterial milking' process that corrodes equipment and produces untreatable saline wastewater. A second engineered strain carries acsAB and acsCD to make its own bacterial cellulose membrane, which is combined with a silk fibroin layer and loaded with ectoine to give a preservative-free, compostable three-layer repair mask. Titres rose from 0.503 g/L (same-batch wild type) to 4.425 g/L in the first engineered strain, 5.344 g/L on an optimised medium and 6.852 g/L after introducing the feedback-desensitised LysC T352I aspartokinase. The team also explored wheat-straw hydrolysate and other paper wastes as non-food carbon sources.","images":[{"url":"https://static.igem.wiki/teams/6236/wiki/description/img1-v2008.avif","caption":"The EcToBloom low-salt green manufacturing platform: engineered chassis, renewable feedstock, biosynthesised ectoine and biodegradable mask, ending in the three-layer BC-Silk-Ectoine repair mask.","credit":"Team ZQT-Nanjing, iGEM 2026 wiki"}]},{"id":"6242","team":"GCGS","section":"High School","country":"China","village":"Infectious Diseases, Therapeutics, Diagnostics & Oncology","wiki":"https://2026.igem.wiki/gcgs/","rank":117,"awards":["Top 10 (High School)","Best New Improved Part — Winner (High School)","Best Presentation — Nominee (High School)","Best Wiki — Nominee (High School)","Best Village Project — Nominee (Infectious Diseases / Therapeutics / Diagnostics / Oncology)"],"projectTitle":"PathoLogic","tagline":"A dual-response engineered E. coli Nissle 1917 probiotic, delivered as an inhalable live biotherapeutic, that degrades Pseudomonas aeruginosa biofilm in cystic fibrosis lungs.","summary":"PathoLogic engineers E. coli Nissle 1917 into a living sensor that fires only when it detects two simultaneous signals of the cystic fibrosis airway — low iron (via Fur) and high C4-HSL quorum-sensing molecule from Pseudomonas aeruginosa (via RhlR) — wired as an AND gate. On dual activation, Lysis E lyses the cells to release alginate lyase, which degrades the alginate-based extracellular polymeric matrix that shields P. aeruginosa from antibiotics and immunity. The product concept is a spray-dried, matrix-protected inhalable live biotherapeutic positioned as an adjunct, not a replacement, for inhaled antibiotics. It won Best New Improved Part on a genuinely instructive two-cycle engineering story: adding SsrA degradation tags to RhlR killed the leakage but also killed the induction, and only replacing the weak wild-type Prhl with the engineered Prhl(LR) recovered a working sensor. The dry lab is the thinnest of the five high-school Top 10 teams; its strength is wet-lab characterisation discipline and an exceptionally thorough regulatory and stakeholder analysis.","images":[{"url":"https://static.igem.wiki/teams/6242/wiki/improve/figure-1.avif","caption":"The modification strategy for the RhlR response system across both improvement cycles: SsrA degradation tags on RhlR, then replacement of wild-type Prhl with the engineered Prhl(LR).","credit":"Team GCGS, iGEM 2026 wiki"}]},{"id":"6243","team":"William-and-Mary","section":"Undergrad","country":"United States","wiki":"https://2026.igem.wiki/william-and-mary/","rank":40,"awards":["Best Measurement — Nominee (Undergrad)","Best Presentation — Nominee (Undergrad)","Safety and Security Award — Winner (Undergrad)"],"projectTitle":"BROKEN: Building Resilient Optimized Engineered Networks","tagline":"Bringing failure analysis from mature engineering disciplines into synthetic biology: detect, mitigate and predict how genetic circuits break.","summary":"William & Mary argued that synthetic biology measures whether a circuit works and almost never measures how long it keeps working. BROKEN therefore ran longitudinal experiments on four previously engineered circuits in laboratory cultures and in seawater microcosms, following them through serial passaging to deterioration rather than stopping at initial success. The team paired functional readouts (OD600, beta-carotene production, GFP, biofilm morphology, starch hydrolysis, colony-forming units) with molecular verification (PCR, restriction digests, gels, NanoDrop) and with multi-omics (RNA-seq, genomic DNA sequencing, long-read plasmid sequencing), then built mechanistic ODE models and machine-learning approaches to predict time to failure. The reliability framing came directly from Integrated Human Practices and turned safety into the project's central motivation, which is reflected in its Safety and Security Award.","images":[{"url":"https://static.igem.wiki/teams/6243/wiki/figures/figure1-betacarotene-assay.avif","caption":"Beta-carotene assay following circuit output over serial passaging. Absorbance at 454 nm is normalised to OD600 so that a fall in total pigment can be separated from a fall in cell number.","credit":"Team William-and-Mary, iGEM 2026 wiki"}]},{"id":"6244","team":"QingdaoAcademy","section":"High School","country":"China","wiki":"https://2026.igem.wiki/qingdaoacademy/","rank":21,"awards":["Best New Basic Part — Nominee (High School)","Best Sustainable Development Impact — Nominee (High School)","Best Village Project — Nominee (Agriculture / Food & Nutrition / Fashion & Cosmetics / Art & Design)"],"projectTitle":"UPKeep","tagline":"From green tides to new possibilities: enzymes that turn collected Ulva into sugars for further biological use.","summary":"QingdaoAcademy (Qingdao, Shandong) built UPKeep around the Ulva prolifera green tides that wash onto the Yellow Sea coast each summer. Stage 1 uses a free, configurable cellulosome - four enzyme modules (Cel9A, Cel6B, Cel9B-N, BglC) docked onto a CBM3a-bearing scaffoldin via cohesin-dockerin pairs - to open the cellulose-rich cell wall; Stage 2 applies an INPNC-Uly1040 ulvan lyase fusion to depolymerise ulvan into oligosaccharides proposed as a cosmetic moisturising ingredient. Containment is an iron-responsive Fur/ccdB-TetR/ccdA toxin-antitoxin circuit, modelled as a 13-state ODE system, while interface selection rests on a 25-pair AlphaFold 3 screen with HADDOCK and PRODIGY follow-up. The Human Practices work is unusually well engineered for a first-year high-school team: thirteen numbered design decisions, each with the stakeholder, what was said, what changed and the follow-up evidence.","images":[{"url":"https://static.igem.wiki/teams/6244/wiki/engagement/qa-8fac1d1be36d-hp01-8fac1d1be3.avif","caption":"HP01: interviews at Hongdao fishing harbour with fishers, boat operators, coastal sanitation workers and residents, which corrected the team's assumption that the Ulva utilisation chain was undeveloped.","credit":"Team QingdaoAcademy, iGEM 2026 wiki"}]},{"id":"6245","team":"ABOA","section":"Overgrad","country":"Finland","wiki":"https://2026.igem.wiki/aboa/","rank":7,"awards":["Best Sustainable Development Impact — Nominee (Overgrad)"],"projectTitle":"Benzophe-none","tagline":"Degrading benzophenone-3 before it reaches our waters","summary":"ABOA (University of Turku) set out to express the benzophenone-3 (BP-3, oxybenzone) catabolic pathway of Rhodococcus oxybenzonivorans in E. coli so that this sunscreen UV filter could be destroyed inside a wastewater treatment plant rather than released into the Baltic and the oceans. The team built a modular restriction-based plasmid system (10 plasmids, 10 genes covering four pathway steps, codon-optimised and RFC10/RFC1000 compatible) that lets homologous flavin reductases and flavin-dependent oxidoreductases be co-expressed, separated, swapped and re-tagged between 6xHis and GST using only NcoI, NdeI and XhoI. Enzyme expression and solubility were obtained to varying degrees, but the activity question was not resolved: BP-3 and BP-1 absorbance overlaps NADH so the spectrophotometric assay was inconclusive, and the triple-quadrupole LC-MS run failed on missing controls and incompatible vials. The team says this plainly and positions the work as a first step plus a designed-but-untested 28-part Golden Gate system (38 parts in total) handed to the community.","images":[{"url":"https://static.igem.wiki/teams/6245/wiki/images/wwtppersonnel-edited.avif","caption":"The team with process engineer Jouko Tuomi and trainees Nea Lempiainen and Heli Karinkanta at the Turku wastewater treatment plant, the meeting that switched the implementation from purified enzymes to whole cells on fixed carriers.","credit":"Team ABOA, iGEM 2026 wiki"}]},{"id":"6249","team":"Heidelberg","section":"Undergrad","country":"Germany","village":"Foundational Advance","wiki":"https://2026.igem.wiki/heidelberg/","rank":129,"awards":["Top 10 (Undergrad)","Best Part Collection — Winner (Undergrad)","Best Wiki — Winner (Undergrad)","Best Foundational Advance Project — Nominee"],"projectTitle":"VOYAGE","tagline":"An acoustic platform for observation and organization of living systems: gas vesicles engineered into a programmable interface between ultrasound and biology.","summary":"Fluorescence microscopy sees molecular detail but light scattering stops it at tissue depth; X-ray reaches deep but uses ionising radiation; ultrasound penetrates deep without radiation and can even push cells around, but has no molecular specificity. VOYAGE closes that gap with gas vesicles — gas-filled protein nanostructures from aquatic microorganisms, built from GvpA with GvpC reinforcing the outer shell — which scatter ultrasound as genetically encodable contrast agents and buckle at a collapse pressure that can be tuned by engineering GvpC. From that one part the team built four capabilities: GvpC variants with distinct pressure responses as a basis for multiplexed acoustic imaging, a kinase-responsive GvpC that turns phosphorylation into an acoustic signal, latch-based biosensors that report soluble targets, and DARPin- or SpyCatcher-directed vesicles that act as acoustic handles, enriching labelled HEK293T cells roughly tenfold at the side outlet of an acoustophoretic chip and lining them up at pressure antinodes while unlabelled cells sit at the nodes. It won Best Wiki and Best Part Collection because the delivery matched the science: a modular part collection with expression systems for Dolichospermum flos-aquae gas vesicles in mammalian cells and Serratia gas vesicles in E. coli, an accessibility guide for working with gas vesicles on a budget, and ATLAS — a full computational companion spanning all-atom molecular dynamics, three protein design pipelines, a fine-tuned segmentation model and an ultrasound signal model.","images":[{"url":"https://static.igem.wiki/teams/6249/wiki/img/model/gvpc-evolution-pipeline.svg","caption":"The complete in silico GvpC redesign pipeline: the template is split into interface and structural residues, interface redesign is deep-learning-guided with LigandMPNN while structural residues are chosen rationally, candidates are predicted and filtered by structure predictors and physical constraints, and validated variants feed back to retune the gating strategy.","credit":"Team Heidelberg, iGEM 2026 wiki"}]},{"id":"6254","team":"UAlberta","section":"Undergrad","country":"Canada","village":"Therapeutics","wiki":"https://2026.igem.wiki/ualberta/","rank":110,"awards":["Top 10 (Undergrad)","Inclusivity Award — Nominee (Undergrad)","Best Entrepreneurship — Winner (Undergrad)","Best Therapeutics Project — Nominee"],"projectTitle":"gleyeco","tagline":"A modular fusion protein that uses the eye's own sugar coating as an anchor, delivered in a hydrogel, so dry eye medicine stays put.","summary":"Dry eye disease affects an estimated 34.6% of people globally and 21.3% of Canadian adults, and the central problem is not the drug but the delivery: blinking and tear drainage clear a topical therapeutic within minutes. gleyeco treats the ocular glycocalyx as a docking site rather than a barrier, fusing a Galectin-3 carbohydrate-recognition domain (binding Core 1 O-glycans on mucins), a tandem pair of the 12-residue hyaluronic-acid-binding peptide HABpep, and IL-1RA (anakinra) as the therapeutic payload, delivered from a crosslinked PEG/hyaluronic acid hydrogel as a drop or a contact lens. The team built a five-stage dry lab pipeline with its own acronyms - GLARE, InSiGHT, VOIR, I-SPY, HOPE - that chooses the target, engineers the binder, sets the valency, predicts the yield and tunes the gel, and released GLARE as an installable Python package. It won Best Entrepreneurship on an unusually rigorous commercial case (38-patient survey, two clinician letters of support, a letter of intent from a clinic, competitor matrix against Restasis/Cequa/Xiidra, PESTEL, 10-year plan) and was nominated for the Inclusivity Award for an open-access Inclusivity in Research course, an Adaptive Technology Kit and a rural teachers' programme.","images":[{"url":"https://static.igem.wiki/teams/6254/wiki/model-page/glare-fig1.avif","caption":"GLARE, the glycan-lectin screening pipeline: 50,000+ catalogued glycan sequences filtered to the 134 documented in ocular tissue, then screened for Galectin-3 off-target risk across other organs and under a dry-eye disease signature.","credit":"Team UAlberta, iGEM 2026 wiki"}]},{"id":"6264","team":"NBJF","section":"High School","country":"China","village":"Space / Foundational Advance (Best Village Project nominee; the village is not named on the wiki, but the project is framed as DNA data storage for long-duration spaceflight)","wiki":"https://2026.igem.wiki/nbjf/","rank":14,"awards":["Best New Basic Part — Nominee (High School)","Best Village Project — Nominee (Space / Foundational Advance / Software & AI / Biomanufacturing)"],"projectTitle":"AI-assisted de novo design of a thermostable TdT for enzymatic DNA synthesis","tagline":"Redesigning nature's DNA typewriter so information can be written into DNA","summary":"NBJF tackled the write step of DNA data storage. Enzymatic DNA synthesis using terminal deoxynucleotidyl transferase (TdT) avoids the toxic chemistry of phosphoramidite synthesis, but wild-type TdT has a melting temperature of roughly 40 C and a catalytic pocket that does not accommodate bulky modified nucleotides. Over seven Design-Build-Test-Learn cycles the team built an AI-assisted de novo protein design pipeline (RFdiffusion backbone generation, ProteinMPNN/LigandMPNN inverse folding, ESMFold and AlphaFold refolding checks, TemStaPro and SaProt thermostability scoring), screened a large candidate library down to a shortlist, expressed 85 designs, and obtained a de novo TdT that retains DNA extension activity at elevated temperature and accepts oxyamino-modified nucleotides. A final cycle used 100 ns molecular dynamics at 300/350/400 K to explain why.","images":[{"url":"https://static.igem.wiki/teams/6264/wiki/engineering/img1.avif","caption":"The seven Design-Build-Test-Learn cycles, from the first unconstrained de novo design through structural reanalysis of wild-type TdT, pocket enlargement, expression screening and the closing molecular-dynamics cycle.","credit":"Team NBJF, iGEM 2026 wiki"}]},{"id":"6269","team":"UZurich","section":"Overgrad","country":"Switzerland","village":"Conservation","wiki":"https://2026.igem.wiki/uzurich/","rank":98,"awards":["Top 10 (Overgrad)","Best Model — Nominee (Overgrad)","Best Presentation — Nominee (Overgrad)","Best Wiki — Nominee (Overgrad)","Best Conservation Project — Nominee"],"projectTitle":"SeisMIC","tagline":"Stabilising Alpine slopes from within: engineered bacteria precipitate calcite between soil grains, with four linked models deciding where it is worth doing.","summary":"SeisMIC adapts microbially induced calcite precipitation (MICP) to Alpine slope stabilisation, where heavy rainfall is now 26% more frequent and 12% more intense and concrete anchoring is often out of proportion to the risk. Sporosarcina pasteurii hydrolyses urea so calcium carbonate crystallises around soil particles, filling pores and binding loose grains, and the team worked on the four limits that stop MICP transferring to the Alps: uneven cementation, scaling across large slopes, cold sensitivity and ammonium production. The distinctive contribution is the dry lab, which is a geospatial and economic decision system rather than a protein pipeline: an infinite-slope Factor of Safety model run across all of Switzerland on daily historical rainfall, a PHREEQC reactive transport model of calcite formation down a soil column, a QGIS MICP feasibility map, and an economic model using Flow-Py runout simulation to put a Swiss franc figure on damage avoided. The models are linked to each other and were reshaped by named expert feedback, which is what earned the Best Model nomination.","images":[{"url":"https://static.igem.wiki/teams/6269/wiki/stability-model/pipeline-overview.avif","caption":"The slope stability modelling pipeline, which joins rainfall records, landslide inventories, terrain and soil data into an infinite-slope Factor of Safety calculation and outputs the extra cohesion MICP would need to supply.","credit":"Team UZurich, iGEM 2026 wiki"}]},{"id":"6278","team":"Stanford University","section":"Undergrad","country":"USA","village":"Therapeutics","wiki":"https://2026.igem.wiki/stanford-university/","rank":230,"awards":["Grand Prize Winner (Undergrad)","Top 10 (Undergrad)","Best Model — Nominee (Undergrad)","Best Wiki — Nominee (Undergrad)","Best Therapeutics Project — Winner"],"projectTitle":"KelePatch","tagline":"A logic-gated, cell-state-specific RNA therapy for keloid scars, delivered by a microneedle patch shaped to the wound.","summary":"KelePatch builds an ADAR-based RADAR RNA sensor that only switches on inside keloid myofibroblasts, so a therapeutic payload is produced in diseased cells and not in healthy skin. The team designed a 26-part modular sensor collection across five fibrosis transcripts (ADAM12, POSTN, ASPN, COL11A1, SPP1), validated them in HEK293 cells, combined the two best into a dual-input AND gate for extra selectivity, and tested in healthy dermal fibroblasts and keloid-derived fibroblasts; they also paired a sensor with Cas12a2 to show the output is not limited to fluorescent reporters. Alongside the wet lab they built RADAR-Scout, a published web platform that takes a cell type and a gene and returns a ranked, structure-aware list of RADAR sensor candidates plus a mechanistic simulation of how it will behave. It won the Grand Prize because every layer connects: 960,518 single cells of transcriptomics pick the trigger, ViennaRNA folding energy ranks the sensor, ODE models explain the delay they saw at the bench, and a U-Net++ computer vision pipeline turns a photo of a scar into a 3D-printable patch.","images":[{"url":"https://static.igem.wiki/teams/6278/wiki/m2-fig4-trigger-selection.webp","caption":"Trigger selection in RADAR-Scout: 600 filtered genes ranked across five keloid cohorts on the left (POSTN first at DSS 1.288), with every candidate sensor for the selected gene plotted on the right, so target and sensor are chosen in one view.","credit":"Team Stanford University, iGEM 2026 wiki"}]},{"id":"6280","team":"LYON","section":"Undergrad","country":"France","village":"Bioremediation","wiki":"https://2026.igem.wiki/lyon/","rank":129,"awards":["Top 10 (Undergrad)","Best Education — Nominee (Undergrad)","Best Presentation — Winner (Undergrad)","Best Bioremediation Project — Winner"],"projectTitle":"BioThetis","tagline":"De novo protein binders anchored on cheap cellulose that capture trifluoroacetic acid from industrial water and release it with heat — no living organism in the filter.","summary":"BioThetis goes after trifluoroacetic acid, the smallest and most stubborn PFAS: an NGO found it in 34 of 36 tap water samples across eleven European countries in 2024, activated carbon barely retains short chains, ion-exchange resins are not approved for French drinking water, and reverse osmosis only concentrates TFA five to ten times at enormous energy cost — the elected official in charge of water at the Metropole de Lyon told the team a single installation would run to roughly one billion euros. Their alternative is a protein binder fused to the cellulose-binding module CBM3a, which sticks to ordinary microcrystalline cellulose with no chemical coupling, captures TFA, and gives it back when the column is heated to 65 C so the material is reusable. Because TFA weighs only 114 Da and no natural binder was on offer, they designed binders from scratch with BoltzGen — 10,000 candidates, 6,823 through the filters, top 5 kept, three taken to the bench in two anchor orientations each — and demonstrated dose-dependent TFA binding by nanoDSF that does not respond to difluoroacetic or acetic acid, so the recognition is TFA-specific. They also solved the fluoroacetate dehalogenase DAR3835 to 1.10 A, the highest resolution reported for that enzyme, and said plainly that no density on the processed datasets is attributable to TFA. It won Best Bioremediation and Best Presentation on an unusually honest project: 15 new Registry parts, 25 printable protocols, all code and all dead ends released CC BY 4.0, and a human practices record that names exactly which conversation changed which page.","images":[{"url":"https://static.igem.wiki/teams/6280/wiki/drylab/column-schematic.avif","caption":"The packed-bed filter model in one picture: water carrying TFA at concentration C0 and flow rate Q enters a cellulose column carrying the binder, with curves for C(z,t) dissolved and q(z,t) captured showing the front moving down the bed, and the breakthrough curve as the output.","credit":"Team LYON, iGEM 2026 wiki"}]},{"id":"6283","team":"GYHS","section":"High School","country":"China","wiki":"https://2026.igem.wiki/gyhs/","rank":7,"awards":["Best Sustainable Development Impact — Nominee (High School)"],"projectTitle":"ReefBond: A Mussel-Inspired Bioadhesive for Coral Reef Restoration","tagline":"A mussel-inspired protein material, designed to help coral fragments hold on while they establish a new home.","summary":"GYHS (Guangdong Guangya High School, Guangzhou) built ReefBond, a recombinant fusion protein that joins a mussel foot protein adhesion module (Mfp3-v12 / Mfp3-v15) to an acidic mineralization module (a CARP3-derived peptide, (Asp)8, (DE)6 or (DDE)4) so that surface adhesion and interfacial mineral deposition act at the same coral-substrate interface. Eight fusion designs were expressed in E. coli BL21(DE3) from pET21a; the team reports qualitative surface-retention staining, in vitro CaCO3 deposition with SEM imaging, and a purpose-built two-version underwater test tank with a motor-guided force gauge, five-level wave generator and a six-channel monitoring interface. The project is unusually honest: nearly every claim is paired with what has not yet been measured, and no live-coral test has been done. Human Practices is the spine of the project rather than a decoration - expert and practitioner advice visibly reorders the experimental programme.","images":[{"url":"https://static.igem.wiki/teams/6283/wiki/public/hp/figure-01-hp-overview.webp","caption":"Overview of Human Practices inputs, decisions and project responses: the five strands linking stakeholder advice to design, experiment, safety and follow-up.","credit":"Team GYHS, iGEM 2026 wiki"}]},{"id":"6284","team":"HUST-China","section":"Undergrad","country":"China","wiki":"https://2026.igem.wiki/hust-china/","rank":33,"awards":["iGEMers Prize — Winner (Undergrad & Overgrad)","Best Fashion & Cosmetics Project — Nominee"],"projectTitle":"IRIS","tagline":"Turning discarded cotton textiles into bacterial-cellulose nanocrystal films that reproduce the iridescence of kingfisher feathers, so the Dian Cui craft needs no birds","summary":"HUST-China built IRIS to resolve an ethical problem inside a Chinese intangible cultural heritage: Dian Cui, the court craft of inlaying kingfisher feathers into metal jewellery. Rather than finding another animal substitute, they went after the physics - keratin-and-air microstructures producing angle-dependent structural colour, with melanin absorbing stray light to raise saturation - and reproduced it by growing bacterial cellulose from discarded cotton textiles, converting it to cellulose nanocrystals and self-assembling those into an ordered photonic structure, layered with pigment-based functional layers. Their design philosophy, formed in dialogue with artisans and conservationists, is 'retain the aesthetic core while abandoning the outdated carrier'. They won the peer-voted iGEMers Prize, and the reasons are legible on the wiki: they hosted a regional forum for other teams modelled on the Jamboree itself, and co-produced open science-communication materials with multiple other teams rather than only publishing their own.","images":[{"url":"https://static.igem.wiki/teams/6284/wiki/image/wiki/education-wiki/education1-1.avif","caption":"The three-dimensional positioning map of educational practices: audience age against outreach domain, so every activity occupies a named cell","credit":"Team HUST-China, iGEM 2026 wiki"}]},{"id":"6289","team":"ETH-Zurich","section":"Overgrad","country":"Switzerland","village":"Foundational Advance","wiki":"https://2026.igem.wiki/eth-zurich/","rank":136,"awards":["Top 10 (Overgrad)","Best Part Collection — Nominee (Overgrad)","Best Software — Winner (Overgrad)","Best Wiki — Nominee (Overgrad)","Best Foundational Advance Project — Winner"],"projectTitle":"preCISe","tagline":"A modular tool for precise intracellular delivery using contractile injection systems","summary":"About 79% of the human proteome is intracellular and largely undruggable, and no approved protein therapeutic delivers an exchangeable protein cargo into the cytosol. preCISe engineers Photorhabdus virulence cassettes (PVCs), bacterial extracellular contractile injection systems that act as molecular syringes, into a retargetable delivery platform: a SpyTag/SpyCatcher-attached binder arm swaps the target without re-engineering the cage, demonstrated against CD20 on engineered mammalian cells with a piggyBac Cre-loxP reporter line (preCISion) that turns on GFP only when Cre reaches the cytosol. To raise specificity they added dual targeting, splitting the cargo across two PVCs against two receptors. It won Best Software and Best Foundational Advance because the platform ships as reusable infrastructure: 29 tested protocols, a part collection for evaluating intracellular delivery, and two open-source tools, deCISion and OpenSplitProtein.","images":[{"url":"https://static.igem.wiki/teams/6289/wiki/images/software/opensplitprotein/web1-03-ranked-v3.webp","caption":"OpenSplitProtein's browser interface showing every cut site in an uploaded structure ranked separately for split tolerance and fragment reassembly, instead of a single blended score.","credit":"Team ETH-Zurich, iGEM 2026 wiki"}]},{"id":"6292","team":"Stockholm","section":"Overgrad","country":"Sweden","wiki":"https://2026.igem.wiki/stockholm/","rank":26,"awards":["Safety and Security Award — Winner (Overgrad)"],"projectTitle":"TIDE","tagline":"A yeast that senses bisphenol A and degrades it from the same sensing event, rebuilt as a contained reactor after three experts said open release would never fly","summary":"Stockholm (KTH) built TIDE, a three-plasmid Saccharomyces cerevisiae system: a detection module encoding a synthetic LexA-mER-alpha transcription factor, a degradation module encoding laccase, and a GFP reporter, so that detecting BPA also triggers its breakdown. They assembled by Gibson, verified by sequencing, read GFP by microscopy and 96-well plate, measured laccase by a modified ABTS assay at 420 nm and BPA removal by LC-MS, and built a modular dry-lab pipeline (structure prediction with pLDDT/PAE early screening, then batch docking of a bisphenol analogue panel). They won the Safety and Security Award in the Overgrad section, and the reason is visible in the work: a three-expert advisory board, a formal STPA hazard analysis, a published wastewater-containment guidebook for future teams, and a documented decision to abandon their own central deployment assumption.","images":[{"url":"https://static.igem.wiki/teams/6292/wiki/safety-and-security/figure1-stpa-control-structure.avif","caption":"STPA control structure for TIDE, mapping regulators, developers, operator, the engineered yeast and independent BPA measurement, with control actions as solid lines and feedback as dashed","credit":"Team Stockholm, iGEM 2026 wiki"}]},{"id":"6294","team":"SDU-Denmark","section":"Overgrad","country":"Denmark","wiki":"https://2026.igem.wiki/sdu-denmark/","rank":14,"awards":["Best Alternative Platform — Nominee (Overgrad)","Best Measurement — Nominee (Overgrad)"],"projectTitle":"Shewanode","tagline":"A microbial fuel cell built from scratch, and a measurement workflow for the outer membrane vesicles that carry its electrons.","summary":"SDU-Denmark engineered Shewanella oneidensis MR-1 to improve extracellular electron transfer and built the hardware to measure it: first a two-chamber microbial fuel cell as proof of concept, then a single-chamber design with an air-breathing cathode and carbon felt electrode that became the team's primary electrochemical measurement system. The measurement work centres on the outer membrane vesicles that carry the MtrCAB cytochrome complex, asking how to isolate them reproducibly and how to quantify their size, morphology, charge and concentration. Each question is answered with complementary methods, each with stated calibration, controls, replicates and limitations. Along the way the team documented a working anolyte recipe, which the literature generally leaves as 'Shewanella basal medium', and released it for other teams.","images":[{"url":"https://static.igem.wiki/teams/6294/wiki/wetlab/calibration-curve-bca.avif","caption":"Calibration curve for the bicinchoninic acid assay: blank-corrected absorbance at 562 nm against a dilution series of bovine serum albumin, used to convert fraction absorbances into protein concentration.","credit":"Team SDU-Denmark, iGEM 2026 wiki"}]},{"id":"6295","team":"Princeton","section":"Undergrad","country":"United States","village":"Foundational Advance","wiki":"https://2026.igem.wiki/princeton/","rank":205,"awards":["2nd Runner-up (Undergrad)","Top 10 (Undergrad)","Best Part Collection — Nominee (Undergrad)","Best Measurement — Nominee (Undergrad)","Best Foundational Advance Project — Winner"],"projectTitle":"SymPleco: Making Precision Sequestration Sym-ple","tagline":"One M13 phage chassis, any cargo — bulk-capacity adsorption with antibody-grade specificity and light-triggered release.","summary":"SymPleco attacks a trade-off that runs through all remediation chemistry: activated carbon captures a lot but cannot tell similar molecules apart, while monoclonal antibodies bind precisely but need harsh pH or chaotropic salts to release and cannot be recovered or scaled. Princeton's answer is a filamentous M13 bacteriophage used as a programmable adsorbent: sortase A-mediated ligation staples engineered fusion proteins onto the N-terminus of every pVIII copy (making 'furry' phage that bypass classical display size limits), with pIII carrying a Cg-Defensin anchor for PLA filter attachment, a VHH7 nanobody for macrophage clearance, and an AsLOV2 optomonobody that holds cargo in the dark and lets go under 450 nm light. Because swapping the target means swapping only the displayed binder, the team paired it with SymPlify, a de novo binder design pipeline, so a new target does not wait on a new antibody. It won on foundational-advance logic: a genuinely modular chassis demonstrated across three deliberately unrelated applications (melanoma exosome sequestration, Parkinson's alpha-synuclein interception, microcystin/BPA water remediation), backed by an unusually self-critical ODE model and an IRB-approved patient engagement programme.","images":[{"url":"https://static.igem.wiki/teams/6295/wiki/figures/symplify-hotspots-protein.avif","caption":"SymPlify's hotspot selection screen: the protein target rendered in 3D and coloured by PeSTo binding probability, with top hotspot residues listed by confidence so low-scoring ones can be removed to leave the focused patch of three to five that BindCraft works best with.","credit":"Team Princeton, iGEM 2026 wiki"}]},{"id":"6296","team":"KIT","section":"Overgrad","country":"Germany","village":"Foundational Advance","wiki":"https://2026.igem.wiki/kit/","rank":26,"awards":["Inclusivity Award — Winner (Overgrad)"],"projectTitle":"ENCORE - Engineered Nanocompartments for Capture, Optimization and Reactor Engineering","tagline":"A standardized modular Golden Gate toolkit that expresses self-assembling encapsulin nanocompartments with custom cargo in yeast","summary":"KIT, the first iGEM team at Karlsruhe Institute of Technology, built ENCORE: a standardised modular cloning system (the toolKIT) that co-expresses a self-assembling encapsulin protein nanocompartment and its cargo in Saccharomyces cerevisiae, chosen because encapsulins assemble from a single repeating subunit and so need far fewer transcriptional units than bacterial microcompartments or virus-like particles. They won the 2026 Inclusivity Award for work that turned inward rather than outward: instead of role-model campaigns, they asked how tasks are actually distributed inside scientific teams and what role gender plays, surveyed 71 people, ran proper statistics, and published the negative result honestly. The resulting deliverables - a facilitated workshop with moderation guide and printable worksheet, and TeamKIT, a team-and-meeting-culture guide - are the reusable artefacts.","images":[{"url":"https://static.igem.wiki/teams/6296/wiki/human-practices-resp/who-does-what-in-a-team/campus-day-presurvey-heptagon.avif","caption":"The heptagon pre-survey: visitors placed a gender-coded dot on the task category they most often take on in teamwork (n = 58)","credit":"Team KIT, iGEM 2026 wiki"}]},{"id":"6297","team":"McMaster-Canada","section":"Undergrad","country":"Canada","wiki":"https://2026.igem.wiki/mcmaster-canada/","rank":7,"awards":["Best Measurement — Nominee (Undergrad)"],"projectTitle":"Chariot: A Platform Technology for OMV-based Therapeutics","tagline":"Inducible loading of bacterial outer membrane vesicles, plus the standardised generation, isolation and characterisation protocols the field does not have.","summary":"McMaster built Chariot, a platform that loads cargo into bacterial outer membrane vesicles (OMVs) using the VNp tagging system, so that accumulation of a VNp-fused protein forces membrane curvature and vesiculation under an inducible promoter. Having identified that OMV work is held back less by biology than by the absence of standard methods, the team made measurement the project: they characterised VNp-driven OMV generation, benchmarked four isolation methods against a shared filtrate reference, and wrote everything into an openly published Protocol Handbook. Alongside this sits Apollo and Artemis, an in-silico platform combining GFlowNet-based active learning for peptide design with molecular dynamics for VNp-cargo compatibility. The project was shaped by 40 stakeholder interviews run through a purpose-built OMVS framework.","images":[{"url":"https://static.igem.wiki/teams/6297/wiki/measurement/measure-sds-page.avif","caption":"12% SDS-PAGE of E. coli BL21(DE3) pET26b(+) 6xHis-mNeonGreen-VNp6 induction and OMV isolation products. ImageJ densitometry on this gel gave 41% recovery of total extracellular mNeonGreen through the isolation.","credit":"Team McMaster-Canada, iGEM 2026 wiki"}]},{"id":"6301","team":"UCNZ","section":"Undergrad","country":"New Zealand","village":"Biomanufacturing","wiki":"https://2026.igem.wiki/ucnz/","rank":91,"awards":["Top 10 (Undergrad)","Best Presentation — Nominee (Undergrad)","Best Entrepreneurship — Nominee (Undergrad)","Best Biomanufacturing Project — Nominee"],"projectTitle":"NanoBrew","tagline":"Enzymatic production of nanocellulose from brewers' spent grain - turning 39 million tonnes a year of brewing waste into a high-value biomaterial.","summary":"NanoBrew takes brewers' spent grain (BSG), which makes up about 85% of beer brewing waste by weight and is mostly landfilled or sold as cheap animal feed, and extracts nanocellulose from it enzymatically instead of with hot acid and energy-intensive mechanical grinding. The team expressed a Bacillus subtilis xylanase (XynA) to strip hemicellulose and open up the cellulose, plus an ancestrally reconstructed Cel5A endoglucanase fused to a carbohydrate binding module to cut cellulose down to nanofibrils, and tested six construct variants with and without the YebF secretion tag in E. coli. It was Top 10 and nominated for Presentation, Entrepreneurship and Biomanufacturing because the project is framed end to end as a New Zealand circular-economy story - built on a real brewery partnership, grounded in the Maori value of kaitiakitanga, with a full pilot-plant cost analysis and letters of support - and because the team is candid that it never managed to characterise its product. No previous iGEM team had extracted nanocellulose from lignocellulosic plant material rather than growing it bacterially.","images":[{"url":"https://static.igem.wiki/teams/6301/wiki/hp/fig-2.avif","caption":"The causal loop diagram: 12 nodes linking the environmental, economic and social effects of an upscaled NanoBrew process, with each link signed positive or negative and the graph decomposed into balancing and reinforcing loops - including the circular-economy rebound effect raised by regulatory stakeholders.","credit":"Team UCNZ, iGEM 2026 wiki"}]},{"id":"6306","team":"NYCU-Taiwan","section":"Undergrad","country":"Taiwan","wiki":"https://2026.igem.wiki/nycu-taiwan/","rank":26,"awards":["Best Project Promotion Video — Winner (Undergrad & Overgrad)"],"projectTitle":"BITE — Biosensing for Instant Target Pathogen Evaluation","tagline":"A two-chamber swab that turns Cas12a collateral cleavage into a blue colour you can read with your eyes","summary":"NYCU-Taiwan built BITE, a hand-operated two-chamber cartridge for foodborne Salmonella detection: chamber one releases magnetic beads carrying DNA capture probes plus lysis buffer, heat lysis frees bacterial DNA, a magnet concentrates the bead-bound target, then chamber two delivers Cas12a with crRNA and a hairpin reporter whose G-rich segment, once cleaved, folds into a potassium-stabilised G-quadruplex that binds hemin to form a DNAzyme and oxidises TMB from colourless to blue. The point of the design is that the final step needs no instrument. They won Best Project Promotion Video in the Undergrad/Overgrad section, and the same communication discipline runs through the wiki, which is built as a scroll-driven narrative rather than a document.","images":[{"url":"https://static.igem.wiki/teams/6306/wiki/01-home/279-home-walk-dev-base.webp","caption":"One layer of the exploded BITE device walkthrough, built from dozens of separately drawn illustration components so the cartridge can be assembled step by step as the reader scrolls","credit":"Team NYCU-Taiwan, iGEM 2026 wiki"}]},{"id":"6329","team":"Baltimore","section":"High School","country":"United States","wiki":"https://2026.igem.wiki/baltimore/","rank":7,"awards":["Best Entrepreneurship — Nominee (High School)"],"projectTitle":"KeraTINT","tagline":"A chromoprotein-keratin-binding-peptide fusion that colours hair and repairs it in the same step","summary":"Baltimore Biocrew, based at the Baltimore Underground Science Space community lab, engineered fusion proteins joining chromoproteins (aeblue, UM) to keratin-binding peptides so that a semi-permanent dye deposits colour while reinforcing the hair shaft. The entrepreneurship work was run through iGEM's Venture Creation Labs curriculum, the same incubator route their 2023 project RhizeUp took, and it produced an OKR table with numeric key results, a scored risk register, a US-specific patent strategy and a competitor map. Market evidence rests on two IRB-approved consumer surveys (56 then 54 responses, translated into Chinese and Filipino) plus named interviews with a cosmetics founder, two L'Oreal North America hair-colour-lab staff, a cosmetology student and the Boeke Lab at NYU Langone. They were nominated for Best Entrepreneurship in the High School section.","images":[{"url":"https://static.igem.wiki/teams/6329/wiki/entrepreneurship/lbmc.avif","caption":"KeraTINT lean business model canvas identifying local salons and cosmetic companies as first customers","credit":"Team Baltimore, iGEM 2026 wiki"}]},{"id":"6330","team":"HBUT-China","section":"Undergrad","country":"China","wiki":"https://2026.igem.wiki/hbut-china/","rank":52,"awards":["Best New Basic Part — Winner (Undergrad)","Best Oncology Project — Winner"],"projectTitle":"IGNITE — oHSV2-Neo-IL-2","tagline":"An AI-redesigned IL-2 that activates CD8 T cells without expanding Tregs, delivered from an oncolytic HSV-2 into microsatellite-stable cold tumours","summary":"HBUT-China targeted microsatellite-stable colorectal cancer, the roughly 80-85 percent of advanced cases that behave as immunologically cold tumours, by arming an attenuated oncolytic herpes simplex virus type 2 with an engineered interleukin-2. Their Best New Basic Part, Neo-IL-2, is an AI-guided interface redesign that weakens binding to IL-2R-alpha (CD25) while keeping signalling through the IL-2R-beta/gamma-c complex, so it activates CD8 T cells and NK cells without driving the regulatory T-cell expansion and dose-limiting toxicity that have crippled wild-type IL-2. The cassette was recombined into an HG52 backbone already deleted for ICP34.5 (neurovirulence) and ICP47 (TAP inhibition, so MHC class I presentation is restored), replacing a CMV-GFP cassette at the gamma-34.5 locus. They won Best New Basic Part in the Undergrad section and Best Oncology Project.","images":[{"url":"https://static.igem.wiki/teams/6330/wiki/safety/wiki/safety/review-20261019/d-shield-framework.webp","caption":"The SHIELD safety framework, consolidating safety-by-design, wet-lab governance, hardware infrastructure, emergency response, training and outreach into one reusable full-chain paradigm","credit":"Team HBUT-China, iGEM 2026 wiki"}]},{"id":"6337","team":"NJU-China","section":"Undergrad","country":"China","wiki":"https://2026.igem.wiki/nju-china/","rank":33,"awards":["Best Model — Nominee (Undergrad)","Best Software & AI Project — Winner"],"projectTitle":"Starase Atlas — Atlas-BRIDGE, Atlas-COMPASS and Atlas-EDGE for enzyme discovery","tagline":"Given a target reaction and limited experimental resources, which enzyme candidates should a researcher test first?","summary":"NJU-China built a three-part platform around one decision: which enzyme to test next. Atlas-BRIDGE (Broad Retrieval with Inference-Driven Gated Experts) is a dual-tower contrastive retrieval model that will rank any protein it can encode, then lets specialist 'expert' models and two kinds of memory nudge that ranking only where their evidence genuinely applies; Atlas-COMPASS is a natural-language agent front end that resolves entities before it computes anything; Atlas-EDGE is a MySQL/graph knowledge base of compound nodes and enzyme edges built from UniProt, Rhea and ChEBI. The model's recommendation was then taken to the bench: M5AW86 was predicted and confirmed to convert FPP to beta-farnesene by GC-MS, TLC and 1H NMR against empty-vector controls. It won Best Software & AI Project and was nominated for Best Model.","images":[{"url":"https://static.igem.wiki/teams/6337/wiki/model/model.avif","caption":"Atlas-BRIDGE architecture: a shared dual-tower retrieval geometry that will score any encodable protein or reaction, with query-level gated experts and dual (long-term graph plus episodic) memory applying additive corrections only inside their valid scope.","credit":"Team NJU-China, iGEM 2026 wiki"}]},{"id":"6338","team":"ASIJ-Tokyo","section":"High School","country":"Japan","wiki":"https://2026.igem.wiki/asij-tokyo/","rank":21,"awards":["Best Part Collection — Nominee (High School)","Best Education — Nominee (High School)","Best Village Project — Nominee (Space / Foundational Advance / Software & AI / Biomanufacturing)"],"projectTitle":"Project 茶(Sa)kure-it-all","tagline":"Yeast cocultures that produce four plant specialized metabolites from sakura and tea - sakuranetin, quercetin, EGCG and L-theanine - without the plant","summary":"ASIJ-Tokyo engineered Saccharomyces cerevisiae to make four plant specialized metabolites tied to Japanese culture: sakuranetin, quercetin, EGCG and L-theanine. Rather than one overloaded strain, they split pathways across cocultured strains at optimised ratios (7:3 for sakuranetin and quercetin, 5:3:2 for the three-strain EGCG system), with every enzyme cassette behind a GAL promoter and a constitutive pTEF1 fluorescent reporter so strain ratios can be verified before induction. Their education portfolio is unusually broad for a high-school team and explicitly gap-driven: each activity was created to fill a named gap they had identified. They contributed 34 new parts, a no-HPLC semi-quantitative screening workflow and a low-cost DIY bioreactor with full build instructions, all aimed at other resource-limited high-school teams.","images":[{"url":"https://static.igem.wiki/teams/6338/wiki/education/crafting-screenshot.avif","caption":"A crafting station in Village 茶(Sa)kura, the free Unity/C# synthetic biology game built with ABAL Inc. and published on itch.io","credit":"Team ASIJ-Tokyo, iGEM 2026 wiki"}]},{"id":"6339","team":"Muenster-University","section":"Overgrad","country":"Germany","village":"Agriculture","wiki":"https://2026.igem.wiki/muenster-university/","rank":117,"awards":["Top 10 (Overgrad)","Best New Composite Part — Winner (Overgrad)","Best Presentation — Nominee (Overgrad)","Best Wiki — Nominee (Overgrad)","Best Agriculture Project — Nominee"],"projectTitle":"P.A.C. Immunity","tagline":"A modular platform that retrofits native plant immune sensors so a crop detects a pathogen's own protease directly and triggers an instant immune response.","summary":"P.A.C. Immunity rewires plant immunity instead of breeding for it. A plant NLR immune receptor is held inactive by a synthetic blocker peptide containing a protease cleavage site; when a pathogen secretes its effector protease into the host cell - a step many viruses, bacteria, fungi and nematodes cannot skip - the protease cleaves the blocker, the NLR fires, and the plant mounts a hypersensitive response. Because only the cleavage site changes between pathogens, swapping one short sequence retargets the whole system, which is the modularity argument: classical resistance breeding takes years and pathogens overcome new resistances quickly. The bottleneck they hit is that almost no pathogen protease has a known cleavage motif, so the dry lab built ProTEUS (Protease Target Elucidation Using Structural Modeling), a de-novo-binder-style pipeline chaining AlphaFold3, RFdiffusion3 and LigandMPNN with a mechanistically grounded geometric scoring function to generate candidate cleavage peptides for proteases with no characterised substrates at all.","images":[{"url":"https://static.igem.wiki/teams/6339/wiki/dry-lab/figures/fig3.avif","caption":"AlphaFold3 confidence for the four candidate effector proteases before and after excluding disordered N-terminal regions, averaged over 10 samples, with the share of each protein trimmed shown above each bar.","credit":"Team Muenster-University, iGEM 2026 wiki"}]},{"id":"6341","team":"KAUST-KSA","section":"Overgrad","country":"Saudi Arabia","village":"Space","wiki":"https://2026.igem.wiki/kaust-ksa/","rank":143,"awards":["Top 10 (Overgrad)","Best Measurement — Nominee (Overgrad)","Best Hardware — Winner (Overgrad)","Best Wiki — Nominee (Overgrad)","Best Integrated Human Practices — Nominee (Overgrad)","Best Space Project — Winner"],"projectTitle":"SHIHAB","tagline":"SHIHAB (shooting star): resilient microbial chassis and a suitcase bioreactor for on-demand therapeutic protein manufacturing in space","summary":"Stocking an inventory of medicines for long-duration missions costs payload mass, so SHIHAB makes the medicine instead: a small library of lyophilised engineered microbes ('pills'), each producing a different nanobody, plus a compact automated bioreactor and purification train that an untrained astronaut can run. The wet lab integrated Dsup, the tardigrade damage-suppressor protein, genomically into three chassis (Bacillus subtilis, Saccharomyces cerevisiae, Pichia pastoris) and quantified radiation resistance against UV-C and X-ray doses with four complementary readouts, then expressed and purified a payload protein by HisTrap. The dry lab answered which host, what feedstock and when to induce using genome-scale metabolic models plus an ODE layer, and COMSOL CFD decided the rotor geometry for mixing under Mars, Moon and transit gravity. It won Best Hardware and Best Space Project; the whole platform was taken out of the lab and run on desert dunes to prove the 'anywhere' claim.","images":[{"url":"https://static.igem.wiki/teams/6341/wiki/content/hardware/cfd-prototype-3.webp","caption":"COMSOL Multiphysics CFD of the third rotor concept (three rows of small tilted blades) at 200 rpm, comparing bubble fate under Earth, Mars, Moon and transit gravity: the simulation that selected the final rotor geometry.","credit":"Team KAUST-KSA, iGEM 2026 wiki"}]},{"id":"6350","team":"Marburg","section":"Overgrad","country":"Germany","village":"Alternative Platform","wiki":"https://2026.igem.wiki/marburg/","rank":131,"awards":["Top 10 (Overgrad)","Best Part Collection — Nominee (Overgrad)","Best Alternative Platform — Winner (Overgrad)","Best Education — Nominee (Overgrad)","Best Presentation — Nominee (Overgrad)","Best Wiki — Nominee (Overgrad)","Best Foundational Advance Project — Nominee"],"projectTitle":"CLiPPR - Chloroplast Library for inducible PPRs","tagline":"Making the chloroplast switchable: inducible designer PPR proteins paired with synthetic 5'UTRs","summary":"Chloroplasts are arguably the cheapest protein factories available (around 90% of global primary production, up to 70% of a plant cell's protein as transgenic product, linear rather than capital-intensive scaling), but they lack the one tool microbial hosts have: inducibility, so growth and production compete permanently and a toxic product means no plant at all. CLiPPR outsources that inducibility to the nucleus: nuclear-encoded, inducibly expressed synthetic pentatricopeptide repeat proteins are imported into the plastid, where they bind matched synthetic 5'UTRs placed upstream of a chloroplast gene and switch translation up or down by three mechanisms (blocking the start codon, protecting an unstable 5'UTR from exonucleases, or resolving a hairpin over the ribosome binding site). The team designed 30 fully synthetic 5'UTRs de novo, produced, purified and tested 19 new-to-nature PPR proteins, reported the highest transgene expression yet recorded in a chloroplast in vitro, and validated across three systems of rising complexity: chloroplast cell-free extract, Chlamydomonas reinhardtii, and Nicotiana benthamiana. It won Best Alternative Platform and was nominated for Part Collection, Education, Presentation, Wiki and Foundational Advance.","images":[{"url":"https://static.igem.wiki/teams/6350/wiki/src/contents/project/alternative-platform/ccfs-utr-screening-1280.avif","caption":"Screening the library of synthetic 5'UTR and designer PPR pairs in chloroplast cell-free extract, the lowest-complexity of the three test systems; one of these 30 de novo UTRs gave the highest transgene expression yet reported in a chloroplast in vitro.","credit":"Team Marburg, iGEM 2026 wiki"}]},{"id":"6366","team":"Peking","section":"Undergrad","country":"China","wiki":"https://2026.igem.wiki/peking/","rank":21,"awards":["Best Model — Nominee (Undergrad)","Safety and Security Award — Nominee (Undergrad)","Best Conservation Project — Nominee"],"projectTitle":"TermiTox — engineered yeast baits for species-specific termite colony control","tagline":"Two engineered yeast strains, modelled from molecular dynamics to whole-colony collapse, to protect wooden heritage buildings without broad-spectrum pesticide.","summary":"Peking built a genuinely three-scale model of a termite bait. Strain A delivers a pH-gated listeriolysin O mutant that lyses the hindgut protozoa a termite depends on for cellulose digestion; Strain B releases hairpin RNA under hindgut hypoxia to silence RsEG (a termite cellulase) and Hexamerin-1 (a caste-development regulator). The Molecular Model used all-atom MD to verify the H311A-LLO safety premise, the Individual Model is a cohort-ODE system calibrated by MAP fitting against quantitative data extracted from 43 papers, and the Colony Model is a spatially explicit agent-based stochastic simulation of trophallaxis through a two-layer nest network with caste structure. The colony model produced a non-obvious and testable deployment schedule that the team then designed hardware for, plus a dose and collapse-time estimate anchored to published hexaflumuron field trials.","images":[{"url":"https://static.igem.wiki/teams/6366/wiki/model/quick-view/termitox-model-whole-picture-v5.webp","caption":"The whole picture of the TermiTox multiscale model: molecular dynamics of the pH-gated LLO mutant, a cohort-ODE individual model of yeast persistence through payload release to functional decline, and a spatially explicit agent-based colony model of trophallactic spread, with each scale's output feeding the next.","credit":"Team Peking, iGEM 2026 wiki"}]},{"id":"6381","team":"UCL","section":"Undergrad","country":"United Kingdom","wiki":"https://2026.igem.wiki/ucl/","rank":28,"awards":["Best Model — Nominee (Undergrad)","Best Integrated Human Practices — Nominee (Undergrad)","Best Sustainable Development Impact — Nominee (Undergrad)","Best Bioremediation Project — Nominee"],"projectTitle":"SHELLter — capturing cisplatin from patient urine with a chelator made from shellfish waste","tagline":"A point-of-care cartridge that chelates platinum chemotherapy drugs out of patient urine, with the chelator made enzymatically from crab shell.","summary":"About half of each cisplatin dose leaves the patient in urine within days, and UK hospital effluent is not treated for cytotoxics at all. SHELLter intercepts it at the point of care with a monoacetylchitosan chelating ligand produced from shellfish-processing waste by an engineered SmChiA-VcCDA fusion enzyme. The dry lab is presented as four Python files on an interactive laptop — kinetic_model.py, docking_simulation.py, life_cycle_assessment.py and techno_economic_analysis.py — and all four feed each other: the kinetic model sets reaction conditions and predicts how downstream purification affects product yield, that yield drives the techno-economic cost per gram, and the same mass balance underpins the openLCA life cycle assessment. The docking study is a rigorously controlled computational experiment with negative controls, a pre-specified acceptance rule, multiple-comparison correction and a stated power analysis.","images":[{"url":"https://static.igem.wiki/teams/6381/wiki/dockingpipeline.avif","caption":"The ten-stage docking pipeline, with each box naming the stage, what it does and the software used. Stage 0 defines the active sites by measuring them from substrate-bound crystal structures independently of any model built later, and stage 3 builds and verifies the substrates from PubChem — both complete before the work they feed into begins.","credit":"Team UCL, iGEM 2026 wiki"}]},{"id":"6389","team":"UFABC-Brazil","section":"Overgrad","country":"Brazil","village":"Diagnostics","wiki":"https://2026.igem.wiki/ufabc-brazil/","rank":14,"awards":["Best Integrated Human Practices — Nominee (Overgrad)","Best Diagnostics Project — Nominee"],"projectTitle":"Patchlepsy","tagline":"A paper-read toehold biosensor that gives people with epilepsy the one thing they do not have: warning time.","summary":"Patchlepsy is a toehold-switch biosensor designed to detect three tRNA-derived fragments (5'GlyGCC, 5'AlaTGC, 5'GluCTC) whose plasma levels rise before seizures in temporal lobe epilepsy, as reported by Hogg et al. (2019). Each switch releases a different chromoprotein reporter (mRFP1, AmilCP, fwYellow), read by a low-cost ESP32 plus AS7341 multispectral device and logged in a mobile app. To the team's knowledge these are the first toehold switches targeting tRFs rather than microRNAs. The cell-free assays never activated in either a CFPS extract kit or PURExpress, and the team publishes that failure with its two mechanistic hypotheses; the whole-cell system did work, with the GlyGCC/mRFP1 switch reaching a fold change of up to 23 in the presence of its trigger. The whole wiki is bilingual English and Portuguese.","images":[{"url":"https://static.igem.wiki/teams/6389/wiki/human-practices/integrated/fluxograma-hp-english.avif","caption":"The four-step integrated human practices workflow: DataSUS epidemiology, SWOT validation with people with epilepsy, stakeholder interviews, and project refinement.","credit":"Team UFABC-Brazil, iGEM 2026 wiki"}]},{"id":"6391","team":"Oxford","section":"Undergrad","country":"United Kingdom","village":"Agriculture","wiki":"https://2026.igem.wiki/oxford/","rank":47,"awards":["Best Wiki — Nominee (Undergrad)","Best Integrated Human Practices — Nominee (Undergrad)","Best Sustainable Development Impact — Nominee (Undergrad)","Best Agriculture Project — Winner"],"projectTitle":"NECTAR","tagline":"An end-to-end platform for designing, validating, producing and deploying RNAi interventions, stress-tested on Varroa destructor","summary":"NECTAR is a programmable RNAi pipeline: FORAGER (computational dsRNA design with off-target screening against the Apis mellifera transcriptome), microbial production in yeast, and delivery to hives in a pollen patty. Varroa destructor, the single biggest threat to honeybees, is the first real-world case study. The team built HIVE, an explicit four-step human-practices decision procedure (Hear, Investigate, Verdict, Evaluate) run over six open project questions with 28+ named stakeholders including US EPA/FDA/USDA staff, the Chair of the UK Advisory Committee on Releases to the Environment, and the Secretariat of the Convention on Biological Diversity. Stakeholder evidence changed the chassis (living engineered Snodgrassella alvi to heat-inactivated yeast), the delivery format, the off-target screening stage, the survey instrument and the definition of success.","images":[{"url":"https://static.igem.wiki/teams/6391/wiki/assets/drawings/sdg-description.avif","caption":"NECTAR at the centre of four chosen SDGs - 15 Life on Land and 2 Zero Hunger as primary goals, 17 Partnerships and 4 Quality Education as enabling goals - each with its own justification rather than a logo wall","credit":"Team Oxford, iGEM 2026 wiki"}]},{"id":"6395","team":"NUS-Singapore","section":"Undergrad","country":"Singapore","village":"Biomanufacturing","wiki":"https://2026.igem.wiki/nus-singapore/","rank":105,"awards":["Top 10 (Undergrad)","Best Part Collection — Nominee (Undergrad)","Best Presentation — Nominee (Undergrad)","Best Wiki — Nominee (Undergrad)","Best Integrated Human Practices — Nominee (Undergrad)","Best Biomanufacturing Project — Nominee"],"projectTitle":"ORCHID","tagline":"Multiplexed fluorescent stress biosensors in yeast plus a machine-learning layer that turns intracellular stress into the next experiment to run.","summary":"Industrial bioreactors hold hundreds of thousands of litres and a single bad batch is expensive, yet conventional monitoring tracks only physical and chemical parameters such as pH and dissolved oxygen — nothing about what is happening inside the cell. Omics and LC-MS can see inside, but they are offline, destructive and slow enough that results arrive after the batch has finished, so they cannot act on anything. ORCHID puts biosensors for endoplasmic reticulum, oxidative and ATP stress into Saccharomyces cerevisiae as fluorescent reporters readable straight from a plate reader, solves the resulting spectral overlap with a linear unmixing model, and feeds the separated stress signals into SABLe, a neural-network framework that predicts growth, product and stress from process conditions and then proposes which culture to run next. It won nominations across parts, presentation, wiki and integrated human practices because the loop actually closed: SABLe's exploration rule proposed 27 C, the team grew that plate, and the measured product signal reached 491 mApple RFU/OD600 against 204 and 179 at the 24 and 30 C conditions it was trained on.","images":[{"url":"https://static.igem.wiki/teams/6395/wiki/pages/model/ml-stuff/sable-slide-12-exploration-score.avif","caption":"SABLe's acquisition rule made visible: model disagreement across the ten bootstrap networks and distance from already-tested conditions highlight different gaps, and their combined exploration score first selected 27 C, 1 mM DTT and 0.15% galactose as the next culture to grow.","credit":"Team NUS-Singapore, iGEM 2026 wiki"}]},{"id":"6399","team":"Kyoto","section":"Undergrad","country":"Japan","wiki":"https://2026.igem.wiki/kyoto/","rank":21,"awards":["Best Part Collection — Nominee (Undergrad)","Best Model — Nominee (Undergrad)","Best Food & Nutrition Project — Nominee"],"projectTitle":"OiLipase — a protein timer that stops rice-bran lipase without destroying rice-bran protein","tagline":"Degrade the enzyme that spoils rice bran oil, then build a molecular timer that degrades the protease once the job is done.","summary":"Rice bran goes rancid because endogenous lipase attacks the oil after milling. Kyoto tethered trypsin to an interface-seeking carrier so it preferentially cleaves lipase at the oil-water interface, then faced the real problem: once the lipase is gone, unselective trypsin starts eating the valuable albumin and globulin. Their answer is a protein timer — a split HRV 3C protease whose N-terminal half is sequestered by an excess decoy that is also a 3C substrate, producing an autocatalytic, tunable lag before 3C fires and destroys the trypsin. Three models carry the project: an ODE timer model with full sensitivity analysis, an induction-diffusion model that derives an interior optimum for leucine-zipper dissociation rate, and a protease-resistance design model that failed its own experiment and was then rebuilt into CleaveRank, released under GPL-3.0.","images":[{"url":"https://static.igem.wiki/teams/6399/wiki/dry/fig3-timer-core.avif","caption":"Figure 3: the timer working. Without decoy, trypsin falls below 90% in under a minute; with 3.0 uM decoy a 27-minute lag appears. The lower panel shows active 3C held near zero through the whole lag then rising sharply as the decoy runs out — the autocatalysis made visible rather than asserted.","credit":"Team Kyoto, iGEM 2026 wiki"}]},{"id":"6401","team":"HKU-HongKong","country":"Hong Kong","village":"Therapeutics","wiki":"https://2026.igem.wiki/hku-hongkong/","rank":21,"awards":["Best New Composite Part — Nominee (Undergrad)","Best Presentation — Nominee (Undergrad)","Best Therapeutics Project — Nominee"],"projectTitle":"Omni-Patch","tagline":"A cell-free single-layer sodium alginate dressing carrying a de novo TLR4/MD-2 antagonist peptide and FGF2 for hard-to-heal wounds","summary":"Omni-Patch is a cell-free sodium alginate wound dressing loaded with aTi-14, a de novo designed peptide intended to block LPS binding to the MD-2/TLR4 complex, plus FGF2 as a repair-supporting growth factor. The team's first concept used a living chassis secreting a literature peptide (TAP2) under nitric-oxide control via NorR; recombinant TAP2 could not be recovered and the macrophage assay showed no reduction in inflammatory markers, so they pivoted to de novo design and a cell-free carrier. A nitric-oxide diffusion model then showed NO penetration depth was far shorter than the hydrogel thickness needed for exudate handling, which killed the NO-sensing component and reframed the device as open-loop. The wiki is unusually candid: aTi-14 left-shifted FITC-LPS binding at 25 uM in a one-concentration THP-1 M0 screen while five sibling variants did not, but matched qPCR showed no transcript drop, the Griess nitrite run was discarded for bacterial contamination, and no IC50 is claimed.","images":[{"url":"https://static.igem.wiki/teams/6401/wiki/modeling/updated/m4-fig2-closure-curves-and-time.avif","caption":"Module 4 Fisher-KPP wound-closure model: predicted closure curves and closure time, the patient-facing output of the chained model stack.","credit":"Team HKU-HongKong, iGEM 2026 wiki"}]},{"id":"6405","team":"CalPolySLO","section":"Undergrad","country":"United States","wiki":"https://2026.igem.wiki/calpolyslo/","rank":47,"awards":["Best Alternative Platform — Nominee (Undergrad)","Best Measurement — Winner (Undergrad)","Best Education — Nominee (Undergrad)","Best Foundational Advance Project — Nominee"],"projectTitle":"Accessible Science: Expanding the Synthetic Cell Toolkit for All","tagline":"A cheap polyphosphate-powered energy module, a reproducible synthetic-cell fabrication device, and the calibrated ATP assay that makes both measurable.","summary":"Cal Poly SLO built a cell-free and synthetic-cell platform aimed at putting synthetic cells into undergraduate hands. The science problem is that PURE-type cell-free reactions run out of energy and that commercial creatine-phosphate regeneration is one of the most expensive parts of the kit, so the team screened a library of polyphosphate kinase 2 (PPK2) enzymes, filtered from roughly 18,000 sequences down to 16 phylogenetically diverse candidates, that regenerate ATP from cheap inorganic polyphosphate. To compare those enzymes they had to build the measurement first: a scalable, interference-corrected luciferase ATP assay with matched standard curves, published protocols, OpenTrons scripts and Excel templates. They also designed a 3D-printed emulsification 'washboard' and a tip-wipe recovery step to make hand-made vesicles reproducible, and wrote the whole thing into CHEM 471, a new undergraduate synthetic-cell lab course.","images":[{"url":"https://static.igem.wiki/teams/6405/wiki/measurement/meas-opentrons-deck.avif","caption":"The Opentrons OT-2 deck loaded with tip racks and plates; the robot was revived after five years to prepare the EDTA stop plates and the fixed 1:25 and 1:50 dilution plates for the ATP assay.","credit":"Team CalPolySLO, iGEM 2026 wiki"}]},{"id":"6409","team":"RDFZ-China","section":"High School","country":"China","wiki":"https://2026.igem.wiki/rdfz-china/","rank":7,"awards":["Best Sustainable Development Impact — Nominee (High School)"],"projectTitle":"GlacierGuard","tagline":"Protect the ice. Leave less behind.","summary":"RDFZ-China engineered E. coli to produce bacterial cellulose (BC) and built GlacierGuard, a biodegradable BC composite membrane intended to slow localized glacier surface ablation. Three genetic systems support it: heterologous bcsABCD plus a pgm/galU UDP-glucose precursor boost for BC yield, a urease (ureABC) biomineralization module that precipitates white CaCO3 inside the BC fibre network to raise albedo, and a CspA cold-shock-protein module to lower the fermentation temperature needed on the Qinghai-Tibet Plateau. BC production reached 230.6 +/- 15.3 mg/L in C41(DE3), roughly 65.9x the empty-vector control, and covered ice retained 3.2 percentage points more mass than geotextile-covered ice in a refrigerator day-night simulation. The team deliberately deployed only commercially sourced (non-engineered) BC membranes during its Tibet field trial and removed all material before leaving.","images":[{"url":"https://static.igem.wiki/teams/6409/wiki/human-practices/img16.avif","caption":"GlacierGuard stakeholder map plotted on power and interest axes, including non-human stakeholders such as glacier microbial communities and downstream aquatic ecosystems.","credit":"Team RDFZ-China, iGEM 2026 wiki"}]},{"id":"6426","team":"CAU-China","section":"Undergrad","country":"China","village":"Food & Nutrition","wiki":"https://2026.igem.wiki/cau-china/","rank":40,"awards":["Best Hardware — Nominee (Undergrad)","Best Sustainable Development Impact — Nominee (Undergrad)","Best Food & Nutrition Project — Winner"],"projectTitle":"Fungal Sentinel, with the OptiX phone spectrometer","tagline":"A $12 to $30 phone-based spectrometer and the two-client software stack that turns one RAW photograph into a concentration with an uncertainty attached.","summary":"CAU-China built Fungal Sentinel, engineered yeast that senses mould volatiles such as 1-octen-3-ol through a GPCR and reports them as fluorescence, and then built the instrument to read it where the mould actually is. OptiX is a pocket spectrometer that uses the phone's own camera as the detector: a threaded interchangeable excitation source, a sample chamber with light-trap fins, a collection module, a frosted-glass slit, a transmission grating, and two USB-C reference lamps that calibrate wavelength and spectral response per device. The software is two programs implementing one written specification, a Python reference implementation and an Android deployment client, held together by a parity test suite that enforces numerical agreement between them. The result is quantitative fluorescence with a limit of detection of 0.81 nM purified EGFP on an early build with no emission filter.","images":[{"url":"https://static.igem.wiki/teams/6426/wiki/optix-wiki-package/images/design/hero-cad-render.avif","caption":"OptiX, the phone-based spectrometer, rendered from the team's Fusion 360 assembly. Materials cost $12 to $30 per unit excluding the optional filter, because the most expensive component, the detector, is the camera the user already owns.","credit":"Team CAU-China, iGEM 2026 wiki"}]},{"id":"6439","team":"NFLSHS-CHINA","section":"High School","country":"China","wiki":"https://2026.igem.wiki/nflshs-china/","rank":52,"awards":["Best Presentation — Winner (High School)","Best Entrepreneurship — Winner (High School)"],"projectTitle":"CroTeen","tagline":"Microbial crocetin: a controllable cell-factory supplement to saffron farming, taken all the way to B2B ingredient specs","summary":"NFLSHS-China built a fully heterologous crocetin pathway in E. coli (idi, CrtE, CrtB, CrtI, CrtY, CrtZ upstream to zeaxanthin; CsCCD2 plus Neurospora crassa NcALD downstream to free crocetin), then re-engineered it after wet-lab failure from a two-plasmid system into a single-plasmid, two-T7-cassette construct (pET-Ds-Cro) for strain stability under scale-up. They used AlphaFold3, PrankWeb and CB-Dock2 to guide semi-rational mutagenesis of the rate-limiting CsCCD2 enzyme, with the N366G mutant giving a 1.13-fold yield increase confirmed by HPLC. The commercial side is unusually disciplined for a high-school team: a named B2B beachhead, a filed and accepted patent application on the CsCCD2 mutant, two physical MVPs with full formula tables, and an explicit separation of what is designed from what is still unvalidated. They won Best Entrepreneurship and Best Presentation in the High School section.","images":[{"url":"https://static.igem.wiki/teams/6439/wiki/entrepreneurship8.avif","caption":"Patent application for the CsCCD2 mutant, filed and accepted, shown on the entrepreneurship page as the project's first hard IP asset","credit":"Team NFLSHS-CHINA, iGEM 2026 wiki"}]},{"id":"6450","team":"IISER-Kolkata","country":"India","village":"Conservation","wiki":"https://2026.igem.wiki/iiser-kolkata/","rank":21,"awards":["Best Presentation — Nominee (Undergrad)","Best Wiki — Nominee (Undergrad)","Best Conservation Project — Nominee"],"projectTitle":"FINS","tagline":"An estrogen-responsive E. coli biosensor coupled to secreted bacterial laccase, immobilised in PVA-alginate beads as a contained tank inside an existing wastewater treatment train","summary":"FINS detects and degrades estrogenic endocrine disruptors (estrone E1, 17beta-estradiol E2, 17alpha-ethinylestradiol EE2) in wastewater. Module 1 uses EdcR, a TetR-family estrogen-dependent repressor from Caenibius tardaugens, expressed constitutively from BBa_J23105 to hold the Pb promoter shut; estrogen de-represses Pb, a T7 RNA polymerase stage amplifies the partial de-repression, and the output is either mScarlet3 (detection build) or secreted 6xHis-tagged BPul laccase from Bacillus pumilus, which oligomerises estrogens by oxidative coupling in the bulk phase. Module 2 is a holin-endolysin kill switch whose trigger was rebuilt from UV/LexA-SOS to RclR with the rclA promoter after wastewater practitioners pointed out Indian plants disinfect with sodium hypochlorite, not UV, on cost grounds. The project is sited as a discrete tank after secondary treatment and before chlorination, so the plant's own disinfection stage doubles as containment. The dry lab is the standout: 13 coupled ODEs, exact Gillespie and Linear Noise Approximation cross-checks, Fisher information and a Cramer-Rao limit of detection, a lattice-Boltzmann packed-bed solve, and a bespoke C++ elastic network solver released as open software.","images":[{"url":"https://static.igem.wiki/teams/6450/wiki/software/software/quiver-mode-arrows.webp","caption":"The Normal Mode Explorer, Quiver's browser interface: a structure drawn as a ribbon coloured blue to red by displacement with per-residue mode arrows overlaid.","credit":"Team IISER-Kolkata, iGEM 2026 wiki"}]},{"id":"6456","team":"Jilin-China","section":"Undergrad","country":"China","wiki":"https://2026.igem.wiki/jilin-china/","rank":7,"awards":["Best Model — Nominee (Undergrad)"],"projectTitle":"A DNA-based recorder of transient fermentation stress in Pichia pastoris","tagline":"Turn fleeting glucose and oxygen limitation during a fermentation run into permanent, readable marks in DNA.","summary":"Jilin-China built a two-channel genetic event recorder: pGTH1 drives Cre (recording glucose limitation) acting on a lox71/lox66 pair, and PsADH2 drives FLP (recording oxygen limitation) acting on an FRT-LE/FRT-RE pair, each inversion flipping a fluorescent reporter read after the run. Five separate models answer five design questions that experiments could not settle: which synonymous FLP sequence to synthesise, how bulk glucose maps to a promoter input, whether an alginate capsule isolates its cells from the broth, what DNA states the construct can occupy, and which published promoter evidence actually applies. The most striking feature is epistemic discipline: nearly every claim is accompanied by a statement of what the calculation does NOT establish, and when the glucose model's predicted low-glucose crossing time (7.56 h) disagreed with the measured 0.11 g/L at 8 h, the team reported the disagreement and downgraded the 0.05 g/L figure to a scenario threshold rather than a promoter activation threshold.","images":[{"url":"https://static.igem.wiki/teams/6456/wiki/day-lab/model/model-1.avif","caption":"Figure 1: connections among the five models, with solid arrows for within-module workflows and documented design selections and dashed arrows for conceptual interfaces that are explicitly NOT a validated coupled prediction — a distinction that lets a reader see exactly where the chain of evidence is real and where it is aspiration.","credit":"Team Jilin-China, iGEM 2026 wiki"}]},{"id":"6462","team":"Eton-College-UK","section":"High School","country":"United Kingdom","village":"Infectious Diseases, Therapeutics, Diagnostics & Oncology","wiki":"https://2026.igem.wiki/eton-college-uk/","rank":91,"awards":["Top 10 (High School)","Best Education — Nominee (High School)","Best Integrated Human Practices — Nominee (High School)","Best Village Project — Nominee (Infectious Diseases / Therapeutics / Diagnostics / Oncology)"],"projectTitle":"ProteaSign","tagline":"A point-of-care electrochemical sensor that quantifies individual protease activities in chronic wound exudate in about ten minutes.","summary":"ProteaSign is a disposable-cartridge electrochemical diagnostic that separately measures MMP-9 (which degrades the extracellular matrix) and human neutrophil elastase (which degrades the growth factors needed for repair) in chronic wound fluid, turning wound assessment from a visual judgement into a measurement. The sensing interface is a gold electrode carrying methylene-blue-labelled, protease-cleavable peptides whose cleavage is read by square-wave voltammetry, with an independently anchored ferrocene reporter providing internal ratiometric normalisation and a matched non-cleavable peptide control on a second working electrode. The peptide sequences were not guessed: the team built a seven-protease machine-learning substrate predictor trained on 10,472 curated cleavage windows, and validated the predictions with two reprogrammable recombinant sfGFP protease biosensors. It won on the rare combination of genuinely publication-grade dry lab (cluster-aware cross-validation, Laplace-transform kinetics derivations, a physics-based SWV forward model), working hardware, and a human practices programme with over twenty named clinical and industrial stakeholders that visibly moved the design.","images":[{"url":"https://static.igem.wiki/teams/6462/wiki/f09.avif","caption":"Out-of-fold performance of the consensus score for all seven proteases: ROC curves with per-protease detection AUROC, precision-recall curves against a 0.25 prior, and the distribution of held-out positives' consensus percentiles against the uniform null.","credit":"Team Eton-College-UK, iGEM 2026 wiki"}]},{"id":"6463","team":"Yucai-SZ","section":"High School","country":"China","wiki":"https://2026.igem.wiki/yucai-sz/","rank":7,"awards":["Best Measurement — Nominee (High School)"],"projectTitle":"SpotAway: a dry-activatable emergency stain patch","tagline":"De novo designed pigment binders and a lipase fusion, measured with explicit methodological boundaries on every assay.","summary":"Yucai-SZ designed SpotAway, a concept for a portable dry patch that treats fresh oil stains where they happen. The functional layer pairs a cellulose-binding-module fusion carrying a de novo designed capsanthin binder, for capturing the hydrophobic pigment in chili oil, with a triolein-binding-domain lipase fusion that anchors near oil droplets and hydrolyses triglycerides, all held in a trehalose-mannitol-protected xerogel that is rehydrated with one or two drops of water. The dry lab extended the standard Foundry de novo design pipeline by layering a docking-based binding-ability pre-test onto structural screening, after wet-lab results showed that structural metrics alone could not rank candidates. What distinguishes the measurement work is that every assay is published with a section defining what it cannot show.","images":[{"url":"https://static.igem.wiki/teams/6463/wiki/wetlab-oct15/figure-17a5a3588f362703.avif","caption":"Standard curves for the lead binder at 275 nm: a protein quantification curve in petroleum ether (R2 = 0.990) used to account for protein background, and the delta-OD against concentration curve for Binder-2 in the capsanthin system (R2 = 0.993), both declared valid only over 0 to 1.5 mg/mL.","credit":"Team Yucai-SZ, iGEM 2026 wiki"}]},{"id":"6475","team":"BGCFullerton","section":"High School","country":"United States","wiki":"https://2026.igem.wiki/bgcfullerton/","rank":7,"awards":["Best Model — Nominee (High School)"],"projectTitle":"MycoVela — helping mycorrhizal fungi establish with plants in lunar regolith simulant","tagline":"Protect arbuscular mycorrhizal fungi from the oxidative chemistry of lunar regolith so they can form symbiosis with crops off Earth.","summary":"Lunar regolith generates hydroxyl radicals and stunts plant growth, and arbuscular mycorrhizal fungi (AMF) are the obvious partner to help plants reach nutrients in it — if the spores survive long enough to germinate. MycoVela tests whether pyomelanin, catalase, trehalose and calcium alginate can protect AMF during establishment in regolith simulant. The dry lab is a five-part collection built by a Boys and Girls Club team drawing students from ten schools, and its statistical standard is genuinely graduate-level: a 34-parameter Monte Carlo oxidative-stress simulation, a Fisher-information identifiability and Sobol sensitivity analysis that found exact degeneracies and an unobservable parameter and so changed the model's own equations, a hierarchical Bayesian dose-response model with partial pooling across three laboratories and 400 simulation-based calibration runs, a reproducible image-analysis tool (MycoLens) whose failure cases are published alongside its successes, and a structural screen of KatE catalase surface variants.","images":[{"url":"https://static.igem.wiki/teams/6475/wiki/models/models/source-p35-1.avif","caption":"Figure 4.2: sensitivity of each planned measurement to each of the 34 model parameters. Darker cells mean the measurement responds more strongly and is therefore more useful for estimating that parameter — germination tracks the stress and damage parameters, hyphal length the growth parameters, peroxide and superoxide the pigment chemistry, and surface coverage almost nothing.","credit":"Team BGCFullerton, iGEM 2026 wiki"}]},{"id":"6478","team":"Athens","section":"Overgrad","country":"Greece","village":"Conservation","wiki":"https://2026.igem.wiki/athens/","rank":136,"awards":["Top 10 (Overgrad)","Best Model — Nominee (Overgrad)","Best Education — Nominee (Overgrad)","Best Entrepreneurship — Winner (Overgrad)","Best Conservation Project — Winner"],"projectTitle":"ApiconIASIS","tagline":"Healing honeybees, sustaining pollinators: a precision phage-derived enzyme therapy for European Foulbrood","summary":"ApiconIASIS targets European Foulbrood (EFB), a statutory honeybee brood disease caused by Melissococcus plutonius for which the only legal response in most of Europe is burning the colony. The team mined 165 M. plutonius genomes for dormant prophages, ranked hundreds of candidate lysins and selected two enzymes (an endolysin and a GH25 muramidase), each built with and without a fused antimicrobial peptide, expressed and purified in E. coli. They showed roughly 40% loss of OD600 against M. plutonius (LMG 20360) with 50 ug/mL purified endolysin while producing no effect distinguishable from the untreated control against the bee-gut commensals Lactobacillus apis and Bombilactobacillus mellis, both Lactobacillales like the pathogen. It won because the whole chain is closed: a protein (not a replicating phage) delivered in brood food, three linked dry-lab models (protein optimisation, larval-gut pharmacokinetics, bioprocess scale-up), and an entrepreneurship case built on the cost of hive burning.","images":[{"url":"https://static.igem.wiki/teams/6478/wiki/optimization/fig7-pareto.avif","caption":"Pareto front from the NSGA-II search over the 17 mutable positions, trading predicted solubility against thermostability (ddG) for the GH25 muramidase; variants A, B and C were selected along this front.","credit":"Team Athens, iGEM 2026 wiki"}]},{"id":"6479","team":"PSI Korea","section":"High School","country":"South Korea","village":"Biomanufacturing / materials and measurement (Best Village Project nominee; the village is not named on the wiki)","wiki":"https://2026.igem.wiki/psi-korea/","rank":21,"awards":["Best Presentation — Nominee (High School)","Best Wiki — Nominee (High School)","Best Village Project — Nominee (Space / Foundational Advance / Software & AI / Biomanufacturing)"],"projectTitle":"Bio Color ID - design and validation of a product authentication system using synthetic biology","tagline":"An authentication tag whose identity is the material itself, read as 60 optical features","summary":"Bio Color ID is a counterfeit-detection tag made by casting biologically produced indigoid pigments into bacterial PHB, so that the authentication feature is the material's own optical response rather than a printed code that can be copied or transferred. Two pathways were engineered into E. coli - phaCAB for PHB from acetyl-CoA, and a tryptophan-derived halogenated-indigoid route - with the team solving substrate competition between the halogenase and TnaA by deleting chromosomal tnaA by lambda-Red, moving the host to BL21-AI to stop T7 leakage, screening seven TnaA variants for intermediate rather than maximal activity, and screening six halogenases before settling on SttH. Tags are then read by a team-built reader: a camera plus five LEDs over four coloured backgrounds, giving 60 RGB features per tag. The team shows that three independently fabricated tags agree to Pearson r >= 0.9977 (MAE 3.58 DN) while visually indistinguishable tags and watercolour paper imitations separate clearly.","images":[{"url":"https://static.igem.wiki/teams/6479/wiki/description/figure-11-reader-assembly.webp","caption":"Assembly of the Bio Color ID Reader: a fixed camera, a hemispherical shell carrying five LEDs (405, 525, 625, 660 nm plus broadband white) and a tag holder over four coloured background panels.","credit":"Team PSI Korea, iGEM 2026 wiki"}]},{"id":"6485","team":"WUXI-DSAS","section":"High School","country":"China","wiki":"https://2026.igem.wiki/wuxi-dsas/","rank":7,"awards":["Best Sustainable Development Impact — Nominee (High School)"],"projectTitle":"ReNovo","tagline":"A hidden signal in a drop.","summary":"ReNovo is a whole-cell E. coli biosensor for urinary gentisic acid (2,5-dihydroxybenzoic acid), built as a non-invasive early-screening route for renal cell carcinoma (RCC), which is 80-85% of primary kidney malignancies and asymptomatic exactly when it is curable. The team adapted the maleylpyruvate-responsive GtdR/PgtdA system of Cupriavidus necator, deliberately omitting the gtdT transporter from the published circuit to obtain a monotonic, quantifiable dose-response, and used mCherry to dodge urine's green autofluorescence. Because urinary analyte concentration tracks hydration, a parallel colorimetric creatinine assay is run on the same chip and the result is reported as a gentisic acid-to-creatinine ratio in a three-tier risk band. The second-generation sensor PG2 gave a linear response over 0-12 uM (y = 1.094x + 16.8, R2 = 0.9764) with no significant artificial-urine matrix effect and no cross-reactivity to 2-, 3-, 4-HBA or salicyluric acid.","images":[{"url":"https://static.igem.wiki/teams/6485/wiki/sustainability-figure-01-concentric-impact-framework.avif","caption":"ReNovo's concentric SDG framework: SDG 3 at the clinical core, SDGs 4/9/12 at the user interface, and SDGs 8/10/17 in the outer ripple, with layer position set by causal distance rather than importance.","credit":"Team WUXI-DSAS, iGEM 2026 wiki"}]},{"id":"6497","team":"Worldshaper-Shanghai","section":"High School","country":"China","wiki":"https://2026.igem.wiki/worldshaper-shanghai/","rank":7,"awards":["Best Entrepreneurship — Nominee (High School)"],"projectTitle":"SweetCycle","tagline":"Don't sell the molecule, sell the step that makes it cheap to separate: engineered glycosyltransferases licensed into existing Reb A refineries","summary":"Worldshaper-Shanghai engineered the two glycosyltransferases that perform the final steps to Rebaudioside M (SrUGT76G1 and SrUGT91D2), screened eight designed variants in a contained Stevia hairy-root chassis with qPCR and HPLC read-out, and found that T284I raised Reb M to 21.96 micrograms per gram fresh weight against 15.44 for wild type while the SrUGT91D2 variants did nothing. The commercial insight is genuinely original: Reb M is expensive not because the pathway is hard but because it sits at about 2 percent of a pool of near-identical glycosides, so the only lever that matters is raising that fraction (eta), and the party who benefits is whoever owns the separation column. They therefore sell a licensed process asset to Reb A refiners rather than a product, backed by a published, recomputable techno-economic model that ranks three production routes and finds their own current enzyme performance gives a negative NPV in every scenario. They were nominated for Best Entrepreneurship in the High School section.","images":[{"url":"https://static.igem.wiki/teams/6497/wiki/worldshaper-shanghai/entrepreneurship/image3.webp","caption":"Positioning map of cost per sucrose-sweetness equivalent on a log scale, showing sucralose at 0.33 RMB/SSE as the ceiling over the whole natural-sweetener category","credit":"Team Worldshaper-Shanghai, iGEM 2026 wiki"}]},{"id":"6511","team":"Labi-Taiwan","section":"High School","country":"Taiwan","wiki":"https://2026.igem.wiki/labi-taiwan/","rank":33,"awards":["Best Measurement — Nominee (High School)","iGEMers Prize — Winner (High School)"],"projectTitle":"BlueCatcher: a cell-free electrochemical biosensor for MDD-associated circulating microRNAs","tagline":"A multistep biosensor validated stage by stage, from three-way-junction target recognition to a calibrated square-wave voltammetry readout.","summary":"Labi-Taiwan built BlueCatcher, a portable cell-free electrochemical biosensor for circulating microRNAs associated with major depressive disorder, intended as objective biological evidence alongside clinical assessment rather than as a diagnosis. The signal chain is deliberately long: a three-way junction recognises the target miRNA and releases a trigger strand, the trigger activates a toehold switch that expresses a nuclease, the nuclease cleaves a methylene-blue-labelled DNA reporter, and the released reporter is captured on a gold-modified screen-printed carbon electrode and quantified by square-wave voltammetry. Because a final signal alone cannot show that every step behaved, the team built a stepwise measurement framework in which each stage is independently validated before integration, with the degree of calibration deliberately matched to each measurement's role. The project also carries a machine-learning design suite and a strong education programme grounded in its own 432-respondent survey; it won the iGEMers Prize in the High School section.","images":[{"url":"https://static.igem.wiki/teams/6511/wiki/wet-lab/measurement/v2/figure-23.avif","caption":"Square-wave voltammetry quantification of the methylene-blue reporter on functionalised Au@SPCEs across 0 to 500 nM. The inset shows the approximately linear relationship between peak current and log concentration (R2 = 0.9457), from which a blank-derived limit of detection of 7.53 nM is calculated.","credit":"Team Labi-Taiwan, iGEM 2026 wiki"}]},{"id":"6520","team":"Al-Nahrain-IRAQ","section":"Undergrad","country":"Iraq","wiki":"https://2026.igem.wiki/al-nahrain-iraq/","rank":26,"awards":["iGEM Spirit Award — Winner (Undergrad & Overgrad)"],"projectTitle":"SYNOVA","tagline":"The first Iraqi iGEM team: a software platform and home-built bioreactor for turning date-palm waste into bioethanol, built under hard local constraints","summary":"Al-Nahrain-IRAQ is the first Iraqi team ever to compete in iGEM, from Al-Nahrain University, with a team drawn from Biotechnology, AI & Robotics Engineering, Civil Engineering and Business Economics. SYNOVA tackles yeast fermentation of date-palm waste into bioethanol, with a software platform of four apps whose governing rule is that a prediction must never be presented as a measurement, so predicted, published-measured and your-own-lab-measured results are kept separate and never combined into one number. The project is defined as much by what Iraq lacks: no local S. cerevisiae collection to borrow, no liquid ethanol sensor purchasable anywhere in Iraq or neighbouring countries at a reasonable price or wait, no local gene bank because of national restrictions, and RT-qPCR primers that took months and arrived only on 19 October. They built the sensor themselves, isolated four candidate wild yeasts from local sourdough, pomegranate vinegar, date vinegar and an overripe date from Najaf, and set an explicit goal of leaving behind protocols, tools and trained people that the next Iraqi team can start from.","images":[{"url":"https://static.igem.wiki/teams/6520/wiki/hp-education/banana-dna-interactive-learning-01.avif","caption":"Banana DNA extraction with schoolchildren at Ajyal Al-Amal and Sarh Baghdad schools","credit":"Team Al-Nahrain-IRAQ, iGEM 2026 wiki"}]},{"id":"6523","team":"NIS Almaty-Medeu","section":"High School","country":"Kazakhstan","wiki":"https://2026.igem.wiki/nis-almaty-medeu/","rank":7,"awards":["Inclusivity Award — Nominee (High School)"],"projectTitle":"MiRVOX (Pulmora and OncoNose)","tagline":"Two approaches to accessible lung cancer screening: programmable RNA detection of blood microRNAs, and exploratory breath volatile organic compound patterns","summary":"NIS Almaty-Medeu built MiRVOX, two parallel platforms for accessible lung cancer research: Pulmora, a synthetic biology platform for programmable detection of circulating microRNAs in blood, and OncoNose, an exploratory engineering project on volatile organic compound patterns in exhaled breath. The team states plainly on its landing page that neither platform is a clinically validated diagnostic test. The project is framed by hard numbers - 2.5 million lung cancer diagnoses and 1.8 million deaths worldwide in 2022, 12.4% of new cancers and 18.7% of cancer deaths, and 4,429 estimated new cases in Kazakhstan where it is the second most diagnosed cancer and the most common cancer in men. Their education and inclusivity work is extraordinarily large for a high-school team and is written with unusual methodological honesty, including a published disagreement between two of their own documents' participant counts."},{"id":"6529","team":"CHINAGuangdongShimen","section":"High School","country":"China","wiki":"https://2026.igem.wiki/chinaguangdongshimen/","rank":7,"awards":["Best Measurement — Nominee (High School)"],"projectTitle":"Re-CDI Alert: an engineered EcN platform for monitoring and treating recurrent Clostridioides difficile infection","tagline":"A p-cresol-sensing probiotic biosensor, characterised with a measurement protocol written so that other teams can repeat it.","summary":"Shimen built an Escherichia coli Nissle 1917 (EcN) biosensor that detects p-cresol, the metabolite Clostridioides difficile produces to suppress competing gut microbes and secure its own niche, and couples detection to a therapeutic output targeting the TcdB toxin. Because recurrence after CDI treatment is diagnosed only once symptoms return, the aim is to shift from symptom-triggered diagnosis toward proactive risk sensing during the post-treatment window. The dry-lab contribution is the measurement protocol itself: a documented, reusable workflow for characterising a small-molecule biosensor, covering plate layout, normalisation, chassis comparison, tolerance limits, dose response and specificity against structural analogues.","images":[{"url":"https://static.igem.wiki/teams/6529/wiki/public/measurement/measurement-figure-01.webp","caption":"Measurement figure from the Re-CDI Alert characterisation workflow, which reads GFP fluorescence at 485 nm excitation and 528 nm emission alongside OD600 so that every value can be normalised per unit biomass.","credit":"Team CHINAGuangdongShimen, iGEM 2026 wiki"}]}];
